insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-5ca586dc-9fde-4995-b268-c2425c0c2cea', 'rw', 'Boundaries (Modifiers)', 'Unlike her ______ predecessor, the new CEO is known for her approachable and friendly demeanor.', 'Which choice best completes the text?', '["aloof","amiable","inexperienced","innovative"]'::jsonb, 0, 'The word ''Unlike'' signals a contrast with the new CEO''s approachable and friendly demeanor; ''aloof'' means distant and unfriendly, providing the needed contrast.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '49413760e6563f07a857ef983890f4684965876a3a774fd8f2eddc896c329e88') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-85023276-49a0-4f24-94f8-d7969faf43e9', 'rw', 'Boundaries (Modifiers)', 'The speaker addressed the audience ______, ensuring that even those in the back could hear every word.', 'Which choice best completes the text?', '["loudly","softly","vaguely","rapidly"]'::jsonb, 0, 'The phrase ''ensuring that even those in the back could hear'' indicates that the speaker used a high volume, so ''loudly'' is the correct modifier.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '20cca4288c7a9eb9d72a754f36eb87e0ccc29d5e5dc91c25a5eaaf11b6cc599e') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-b5a19499-f538-449c-ab10-d94ee4ce2381', 'rw', 'Boundaries (Modifiers)', 'Although the hike was ______, the breathtaking views from the summit made the effort worthwhile.', 'Which choice best completes the text?', '["strenuous","scenic","short","enjoyable"]'::jsonb, 0, 'The contrast signaled by ''Although'' and the phrase ''made the effort worthwhile'' indicate that the hike was difficult, so ''strenuous'' is the correct modifier.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '40f41118ca17d410c1248de21ea81510a0bf596358533f2d3aa79d6a548d3462') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-6182e7ef-faac-40e4-83e0-93775f6163ac', 'rw', 'Boundaries (Modifiers)', 'The novel''s plot is ______, but the characters are richly developed.', 'Which choice best completes the text?', '["predictable","intricate","engaging","original"]'::jsonb, 0, 'The conjunction "but" introduces a contrast; the correct choice "predictable" describes a plot that is unremarkable, contrasting with the richly developed characters.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '15acd554701be4f851288e7112d82cf7a483275dcc1fa6efe6a8e6cda9a8752c') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-fefeb2f9-cd8e-44aa-bcc6-b4e3bef53f87', 'rw', 'Boundaries (Modifiers)', 'While the company''s profits were ______ last quarter, its revenue actually increased.', 'Which choice best completes the text?', '["disappointing","impressive","steady","unprecedented"]'::jsonb, 0, 'The word "While" signals a contrast; the correct choice "disappointing" indicates that profits were poor, contrasting with the increase in revenue.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '2f59ee3b968523f7c3fdb7f620c39f0ee4161cc011eaefa987a7fb71b9b4cbd8') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-68f7361e-469b-451b-9366-a82b41adc777', 'rw', 'Boundaries (Modifiers)', 'The artist''s latest mural, ______ on the side of the old library, has become a beloved landmark.', 'Which choice best completes the text?', '["painted","painting","paint","paintedly"]'::jsonb, 0, 'The modifier must describe the mural, which is the object of the action. ''Painted'' is a past participle that correctly indicates the mural was painted. ''Painting'' would suggest the mural is performing the action, which is illogical. ''Paint'' is a noun or base verb and cannot serve as a modifier. ''Paintedly'' is not a standard adverb and does not fit.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '8fbcf09843e81fefc881ef11a1f28fb719764471b4c7b2e7a1928416df740a78') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-10b13174-587e-4b50-a3bc-c6462bcc1125', 'rw', 'Boundaries (Modifiers)', 'The research team discovered a new species of frog, ______, in the remote cloud forests of Ecuador.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["a tiny, brightly colored amphibian","a tiny brightly colored amphibian","a tiny, brightly colored amphibian,","a tiny; brightly colored amphibian"]'::jsonb, 0, 'The blank contains a nonrestrictive appositive that renames ''a new species of frog.'' The sentence already provides the necessary commas to set off the appositive, so no additional punctuation should appear at the boundaries of the blank. Within the appositive, a comma is required between the coordinate adjectives ''tiny'' and ''brightly colored.'' The correct choice supplies this internal comma without adding extraneous punctuation.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '8673ec967ac84dd0c97df14bb93eed6d29a780560e46e898949f060c7721192e') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-7fcff901-0da6-48ee-9a6e-d79f339cb7c1', 'rw', 'Boundaries (Modifiers)', 'The novel’s protagonist, ______, struggles to reconcile her ambition with her family’s expectations.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["a young lawyer from a small town","a young lawyer from a small town,","a young lawyer, from a small town","a young lawyer; from a small town"]'::jsonb, 0, 'The appositive phrase ''a young lawyer from a small town'' renames the protagonist and is nonrestrictive. The sentence already supplies the necessary commas before and after the blank, so no additional punctuation should appear within the blank. The correct choice contains no extra punctuation.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '8a262cfa837649c07b2c86365cb5d82e403cedc2fea639772da41a55f9e88851') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-9ce065f2-a4e2-4e27-b2b1-e40691d0c497', 'rw', 'Boundaries (Modifiers)', 'After being meticulously restored by a team of experts, ______.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["the vintage car gleamed in the showroom.","the showroom displayed the vintage car.","it was the vintage car that gleamed.","the gleam of the vintage car was impressive."]'::jsonb, 0, 'The modifying phrase ''After being meticulously restored by a team of experts'' must logically modify the subject of the main clause. The subject should be the entity that was restored. ''The vintage car'' is the only choice that can be restored; the other choices incorrectly make the showroom, a dummy ''it,'' or a gleam the subject of the restoration.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'a0ec926b8510fd2432db8f49ce49caf0fbb8a3fd6fd745d00bf397927668b5d1') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-8a26a8d9-4e6b-4cff-9a85-c8826ef5e05f', 'rw', 'Boundaries (Modifiers)', 'After waiting for hours, ______.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["the bus finally arrived.","we finally saw the bus arrive.","the arrival of the bus was a relief.","it was a relief when the bus arrived."]'::jsonb, 1, 'The modifying phrase ''After waiting for hours'' must logically modify the subject of the main clause. The subject should be the one who waited. ''We finally saw the bus arrive'' correctly makes ''we'' the subject, indicating that we waited. The other choices incorrectly make the bus, the arrival, or a dummy ''it'' the subject of the waiting.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '1b685a73fc4086f5d370ea2b66b22e2f77847d463eb6ef82c7fcd66ca919ec2b') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-044b7326-a4c6-484a-b655-5dc1a80cf66f', 'rw', 'Boundaries (Modifiers)', 'The researcher''s findings, ______ by several peer-reviewed studies, have significantly influenced the field of neuroscience.', 'Which choice best completes the text?', '["corroborated","contradicted","overlooked","initiated"]'::jsonb, 0, 'The sentence indicates that the findings have had a significant influence, which is most logical if they were supported. ''Corroborated'' means confirmed or supported, fitting the context. ''Contradicted'' would mean the studies opposed the findings, making influence unlikely. ''Overlooked'' suggests the studies ignored the findings, which would not lead to influence. ''Initiated'' is illogical because findings are not initiated by studies.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '9bd5be780e8dc7f1307bef116076a5d17ea717ab774b77e92d188980bd9b166a') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-1a0a47a9-2a2a-4f69-a262-0ebeec310441', 'rw', 'Boundaries (Modifiers)', 'The research team ______ published their findings in a major journal.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["after months of rigorous testing,",", after months of rigorous testing,","after months of rigorous testing",", after months of rigorous testing"]'::jsonb, 1, 'The phrase ''after months of rigorous testing'' is a nonrestrictive modifier providing additional information about the research team. Nonrestrictive modifiers must be enclosed in commas. The correct choice places a comma before and after the phrase.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'acfb87856e4f2380e7bf8e610ca075033a2b6ac4fa1b76e0d71072fc49d26393') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-3f2ffaec-814c-4741-9ef5-3ab5f72daac2', 'rw', 'Boundaries (Modifiers)', '______, the novel''s protagonist emerges as a deeply flawed yet sympathetic figure.', 'Which choice best completes the text?', '["Faced with a series of moral dilemmas","Written in a lyrical prose style","Set in a dystopian future","Having been criticized for its slow pace"]'::jsonb, 0, 'The introductory modifier must logically refer to the subject of the main clause, "the novel''s protagonist." Only "Faced with a series of moral dilemmas" correctly describes the protagonist; the other options incorrectly modify the novel itself, resulting in dangling modifiers.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '123486fee931d4700d25039948c496bed6086021fe08cddae955730fd07980a9') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-2e01c674-c52a-406e-bcb6-5b0aab1c41c1', 'rw', 'Boundaries (Modifiers)', '______, the intricate patterns on the pottery shards suggested a sophisticated artistic tradition.', 'Which choice best completes the text?', '["Carefully analyzed by archaeologists","Excavated from a previously unknown site","Using advanced imaging techniques","After being buried for millennia"]'::jsonb, 0, 'The introductory modifier must logically describe the subject of the main clause, "the intricate patterns." Only "Carefully analyzed by archaeologists" can sensibly modify the patterns; the other choices incorrectly imply that the patterns themselves were excavated, used imaging techniques, or were buried, which creates a dangling modifier.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '489058ea9444a2e0ece4c4cee72f3086102323d02c86191fe682c5ec9124bdd9') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-9ec307fa-554a-4164-90e9-fdd8afe373c3', 'rw', 'Boundaries (Modifiers)', 'The documentary''s portrayal of the controversial leader was criticized for being overly ______, as it omitted any mention of the regime''s human rights abuses.', 'Which choice best completes the text?', '["laudatory","comprehensive","objective","inflammatory"]'::jsonb, 0, 'The clause after the blank indicates the documentary omitted human rights abuses, so the portrayal must have been excessively positive. Laudatory means expressing praise, which fits the context of a one-sided, favorable depiction.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '82e7f40fe303ceb0a130ea950c7b826f797a946b7742ab83d14126b519fc8376') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-16d324d5-1fb7-45d8-9c13-5dff29314241', 'rw', 'Boundaries (Modifiers)', 'To ensure the experiment''s validity, ______.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["the control group must be carefully selected","researchers must carefully select the control group","the selection of the control group is critical","careful selection of the control group is necessary"]'::jsonb, 1, 'The introductory infinitive phrase "To ensure the experiment''s validity" requires a subject that can logically perform the action of ensuring. Only "researchers must carefully select the control group" provides a subject (researchers) capable of carrying out that action. The other choices incorrectly make the control group or the selection itself the subject, creating a dangling modifier.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '9db7da87a2c306bb2dbf3af43226c8e698fc04e9cfcd69da38067d50829d8593') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-b89d7a24-185d-40c5-9ee1-9e41b210b84d', 'rw', 'Boundaries (Modifiers)', 'The painting ______ was sold for a record price at auction.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[", a rare masterpiece from the Renaissance,","a rare masterpiece from the Renaissance,",", a rare masterpiece from the Renaissance","a rare masterpiece from the Renaissance"]'::jsonb, 0, 'The phrase "a rare masterpiece from the Renaissance" is a nonrestrictive appositive modifying "the painting." Nonrestrictive appositives must be set off by commas on both sides. The correct choice places a comma before and after the appositive, while the other choices either omit a required comma or place it incorrectly, creating punctuation errors.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'fa180dd09f5542132645af8fd5b89a25c5aa37bfa2d9d39ace7547d81410306f') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-12fdf265-ab29-4f05-9f65-6c30dde196cc', 'rw', 'Boundaries (Modifiers)', 'The conference featured speakers from three continents ______ Asia, Europe, and South America ______ and covered topics ranging from climate policy to artificial intelligence.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[": ... ;","; ... ,","— ... —",", ... ,"]'::jsonb, 2, 'The phrase ''Asia, Europe, and South America'' is a nonrestrictive appositive that specifies the three continents. Because the appositive itself contains commas, using a pair of dashes to set it off avoids confusion and clearly marks its boundaries. A pair of commas would create a confusing series of commas, and a colon or semicolon is not appropriate for a parenthetical appositive.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '16dcc74f4e944ad67e1653345a1853a2449d56ced59bcbf83aff87d4977b896e') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-20cb3c2f-f74c-4dec-af8a-74566881f22a', 'rw', 'Boundaries (Punctuation)', 'The conference featured speakers from three continents ______ Asia, Europe, and South America.', 'Which choice best completes the text?', '[":",";",","," —"]'::jsonb, 0, 'A colon is used to introduce a list after an independent clause. A semicolon would require a complete clause after it, a comma would create a run-on, and a dash is less appropriate for a straightforward list introduction.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '386d0ee7b598232f568950a0591da1c89d438ce4aa19e5c5f2f085ef1ad22ee7') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-24a3af9a-9913-4201-9a82-d2327b6ac70c', 'rw', 'Boundaries (Punctuation)', 'The library''s new wing houses a vast collection of rare books ______ it also features a state-of-the-art reading room.', 'Which choice best completes the text?', '[";",",",":"," —"]'::jsonb, 0, 'The semicolon correctly joins two independent clauses without a conjunction. A comma would create a comma splice, a colon is used to introduce a list or explanation, and a dash is less formal and not standard here.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '02d71279ebb1086b703a6b579134cc17cbc964e78e6635eb03f9154b6a59182b') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-b1e7b633-f36c-4869-a7c1-6a55a29b5ab0', 'rw', 'Boundaries (Punctuation)', 'After the concert ended ______ the audience gave a standing ovation.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[",",";",":"," —"]'::jsonb, 0, 'A comma is used to separate an introductory dependent clause from the main clause. A semicolon would be incorrect because the first part is not an independent clause. A colon is used to introduce a list or explanation, not to separate a dependent clause from the main clause. A dash would be too abrupt and is not standard here.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'ea8f67a85edae9074a4ec66a57232e6adb2e9f7eb3acadc0d8430e5389131e5d') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-922c80c6-7045-461d-9f79-b1894b4d5dfd', 'rw', 'Boundaries (Punctuation)', 'The museum''s new exhibit features rare artifacts from ancient Egypt ______ and it includes interactive displays for visitors.', 'Which choice best completes the text?', '[", and","and","; and",": and"]'::jsonb, 0, 'The blank is before a coordinating conjunction joining two independent clauses. A comma is required before the conjunction. Using ''and'' alone creates a run-on. A semicolon with ''and'' is redundant. A colon with ''and'' is incorrect.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '944642f14a11db782a99d00a4ceeede2b9a38d2df0286e0dc5b1cb62d9ce21b6') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-31c2615e-c4f6-4ac0-9ed1-c3ec0075e9d2', 'rw', 'Boundaries (Punctuation)', 'The storm intensified rapidly ______ the crew decided to seek shelter.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[";",",","and",":"]'::jsonb, 0, 'The text contains two independent clauses. A semicolon is used correctly to join them without a conjunction. A comma would create a comma splice, ''and'' alone would create a run-on, and a colon is not appropriate because the second clause does not explain or illustrate the first.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '957c6e817d1dcbf0107dc05e3b9b60813befa9cafafa82d122799bea0bb4309a') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-c6690af1-f163-49bf-bb2c-c033aa5e89d7', 'rw', 'Boundaries (Punctuation)', 'The chef prepared a delicious meal ______ the guests were too full to eat dessert.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[", but","; but",", and","but"]'::jsonb, 0, 'The text contains two independent clauses joined by the coordinating conjunction ''but''. A comma is required before the conjunction. Using a semicolon with ''but'' is incorrect, '', and'' changes the intended contrast, and ''but'' alone creates a run-on sentence.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '26813627912d4ae0a5726250003685f4b1bfed45d9e8c3082ecc706b1176e1ae') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-c6ee26a5-0d70-4c10-8c2b-f408da2a30f8', 'rw', 'Boundaries (Punctuation)', 'The storm caused widespread power outages across the region ______ and many residents were left without heat for several days.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[", and","and","; and",": and"]'::jsonb, 0, 'The sentence contains two independent clauses joined by the coordinating conjunction ''and.'' A comma is required before the conjunction to separate the clauses. Omitting the comma creates a run-on. A semicolon or colon before ''and'' is nonstandard.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '74f6c05fdb0c55c5bb9252216b0916563d2b3865d38a98b919da3b02e841490c') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-31ff202c-be2d-4527-996b-c7223a58c7c4', 'rw', 'Boundaries (Punctuation)', 'The experiment yielded unexpected results ______ the researchers decided to replicate it with a larger sample size.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[";",",",":","—"]'::jsonb, 0, 'The text contains two independent clauses. A semicolon is the appropriate punctuation to join them without a conjunction. A comma would create a comma splice. A colon is used to introduce an explanation or list, which is not the case here. A dash would indicate an abrupt shift, but the second clause is a logical consequence.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'dc57674283ff709f3a4d8aa298bd949aac3b13dd8213a881cd21ca7ecace0cf5') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-c0ca71ae-f747-475c-b4aa-628ae4620b13', 'rw', 'Boundaries (Punctuation)', 'The novel’s protagonist, a former detective haunted by a past case ______ struggles to adapt to civilian life.', 'Which choice best completes the text?', '[",",";",":","—"]'::jsonb, 0, 'The phrase ''a former detective haunted by a past case'' is a nonrestrictive appositive that must be set off by commas. A comma is needed after ''case'' to close the appositive before the main verb ''struggles''.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '22c11b1ba7bb2e4c8bf2d439260564b758aa524172ad77dd262d0c847a3dfbd9') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-81a811f7-f423-4980-80b5-042d19c01083', 'rw', 'Boundaries (Punctuation)', 'The conference will feature speakers from Paris, France ______ Tokyo, Japan ______ and Sydney, Australia.', 'Which choice best completes the text?', '[";",",",":","—"]'::jsonb, 0, 'When items in a list contain commas, semicolons are used to separate the items clearly. A semicolon after ''France'' correctly separates the first complex item from the second.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '2e87ee40c92e1288f4f43e3491f11fd93ff213cc1e4e2601205b38e5e7a60a4e') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-4f6b760a-a894-4572-a144-198959c626a0', 'rw', 'Boundaries (Punctuation)', 'The researchers analyzed the data thoroughly ______ and they discovered a significant correlation.', 'Which choice best completes the text?', '[",",";",":"," —"]'::jsonb, 0, 'A comma is needed before the coordinating conjunction ''and'' joining two independent clauses. A semicolon, colon, or dash would be incorrect before ''and'' in this structure.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'f2d863ff8698b6bc2e5f5b17007dcf19288e990f6aed3bda8e7be5ced44cb500') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-5d4a3f6c-0868-45ae-b184-0ccc72f6d43e', 'rw', 'Boundaries (Punctuation)', 'Although the experiment was carefully designed ______ the results were inconclusive.', 'Which choice best completes the text?', '[",",";",":"," —"]'::jsonb, 0, 'A comma is required after the introductory dependent clause ''Although the experiment was carefully designed'' before the main clause. A semicolon, colon, or dash would not be standard punctuation here.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'aa390381b2a19011422263453fa0c694aeb478fbe83b36b51244430c540fc18c') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-49c56a80-aae8-4105-a0fa-8ce26884c933', 'rw', 'Boundaries (Punctuation)', 'The data seemed to support the hypothesis ______ however, a closer examination revealed significant inconsistencies.', 'Which choice best completes the text?', '[";",",",":","—"]'::jsonb, 0, 'The sentence contains two independent clauses joined by the conjunctive adverb ''however.'' A semicolon is required before ''however'' to correctly link the clauses; a comma would create a comma splice. A colon is used to introduce an explanation or list, not to connect contrasting clauses. A dash could set off a parenthetical but is not the standard punctuation for this structure.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '8ad499207b050aca9cc548a2c89e45a6d6ede437bb7fc700012658d615091fd0') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-f82a2732-b7fb-4e8c-8acf-89c1136da342', 'rw', 'Boundaries (Punctuation)', 'The mural''s central figure ______ a stylized phoenix, rising from geometric flames—dominates the composition.', 'Which choice best completes the text?', '["—",",",";",":"]'::jsonb, 0, 'The phrase ''a stylized phoenix, rising from geometric flames'' is a nonrestrictive appositive that renames ''the mural''s central figure.'' Because the appositive itself contains a comma, using commas to set it off would create confusion. A dash is needed to match the dash after ''flames'' and to clearly separate the appositive from the rest of the sentence. A semicolon would incorrectly break the sentence, and a colon is not used for nonrestrictive appositives.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '92b3e69dfc5a226489591a212418f5b3819b92cfc50e31d107df154316743749') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-7b11a258-a323-472f-8979-fe7bfcfbe02a', 'rw', 'Boundaries (Punctuation)', 'The experiment produced unexpected results ______ the researchers decided to conduct additional trials.', 'Which choice best completes the text?', '[";",",",":","—"]'::jsonb, 0, 'A semicolon is needed to join two independent clauses without a conjunction. The second clause is a consequence, not an explanation, so a colon is inappropriate. A comma would create a comma splice; a dash is used for an abrupt break or to set off nonessential information, not to join two independent clauses.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'e59e251e0ccdea2293ed35453b39e361c5dfd0309a79ad3a77e23dd4e4dee1d8') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-21cfbdaa-a5d5-4508-a006-0b94db34a3c0', 'rw', 'Boundaries (Punctuation)', 'Although the committee reviewed the proposal thoroughly ______ it ultimately decided to reject it.', 'Which choice best completes the text?', '[",",";",":","—"]'::jsonb, 0, 'The correct choice is a comma. The sentence begins with a dependent clause ("Although the committee reviewed the proposal thoroughly"), so a comma is needed to separate it from the independent clause that follows. A semicolon is incorrect because it is used between independent clauses. A colon is incorrect because it introduces an explanation or list after an independent clause. A dash is incorrect because it is used for an abrupt break or emphasis, not to separate a dependent clause from the main clause.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'f47b47fd1b22c834c0dedc1c50042c9f1c2893e9038ea9a6ed6466e3c0bce35d') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-205b5b82-1a7f-444e-9b56-27ddebfa439e', 'rw', 'Boundaries (Punctuation)', 'The team collected samples from the site ______ they sent them to the lab for analysis.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[", and","and","; and",","]'::jsonb, 0, 'The sentence contains two independent clauses joined by the coordinating conjunction "and"; a comma is required before the conjunction. The correct choice ", and" provides this comma. The other choices create errors: "and" alone results in a run-on sentence, "; and" incorrectly pairs a semicolon with a conjunction, and a comma alone creates a comma splice.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '1d84cea6499f41a1e9c4210f5f4ef3951d378c8f38fa057889ae380887ba3f87') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-0735a9d0-ba53-460e-a3b6-1d21377a3473', 'rw', 'Boundaries (Punctuation)', 'The experiment ______ which was conducted over three years, yielded surprising results.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[",",";",":","—"]'::jsonb, 0, 'The clause "which was conducted over three years" is a nonrestrictive relative clause modifying "experiment". It must be set off with a comma at the beginning (the comma after "years" is already provided). The correct choice "," supplies this comma. A semicolon or colon would incorrectly separate the subject from its modifier, and a dash would require a matching dash after the clause, which is not present.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'e5aff23e50641c662e28c203b0b027477b9a2ae54befd94f26409b10e3133b5f') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-20a00c1d-1041-49b6-b79a-9d047db581fa', 'rw', 'Central Ideas', 'When wolves were reintroduced to Yellowstone National Park in 1995 after a 70-year absence, the ecosystem underwent dramatic changes. The wolves reduced the elk population, which had been overgrazing young willow and aspen trees. As these trees recovered, beavers returned to build dams, creating ponds that supported fish, birds, and other wildlife. The return of a single predator thus triggered a cascade of ecological restoration.', 'Which choice best states the main idea of the text?', '["The reintroduction of wolves to Yellowstone led to widespread ecological recovery.","Elk overpopulation was the primary threat to Yellowstone''s biodiversity.","Beavers are essential for maintaining healthy pond ecosystems in Yellowstone.","Wolves were absent from Yellowstone for nearly a century before their return."]'::jsonb, 0, 'The passage traces a chain of effects from the wolves'' return to the restoration of trees, beavers, and other species, illustrating that the wolves'' presence triggered a broad ecological recovery. The correct choice summarizes this cascade.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'fdb3625fc67814696d6d0239e76c91f2b965871bd947ceb45fe802bb63994386') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-c87e183e-942f-49e5-b65b-7e7ba34327b3', 'rw', 'Central Ideas', 'For decades, scientists believed that tool use was a behavior unique to primates. However, recent observations of the New Caledonian crow have shown that these birds fashion sticks into hooks to extract insects from bark. This finding suggests that complex cognitive abilities may be more widespread in the animal kingdom than previously assumed.', 'Which choice best states the main idea of the text?', '["New Caledonian crows are the only birds known to use tools.","The discovery of tool use in crows challenges the belief that such behavior is limited to primates.","Primates are no longer considered the most intelligent animals.","Scientists have long been interested in the problem-solving skills of birds."]'::jsonb, 1, 'The text contrasts the old assumption that only primates use tools with new evidence of tool use in crows, indicating that the main idea is that this discovery challenges the previous belief.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '85ff94e4a07f7fb9f8f473496716b632ee9090b2ba610b2b4899b16af88616d7') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-9744d928-c48a-4fa9-9f49-96885edb7193', 'rw', 'Central Ideas', 'Although often overshadowed by her male colleagues, Rosalind Franklin''s X-ray crystallography images were crucial to the discovery of the DNA double helix. Her meticulous work provided the key measurements that enabled Watson and Crick to build their accurate model. Without her data, the structure of DNA might have remained unsolved for years.', 'Which choice best states the main idea of the text?', '["Watson and Crick were solely responsible for determining the structure of DNA.","Rosalind Franklin''s contributions to the discovery of the DNA double helix were vital yet frequently underrecognized.","X-ray crystallography is the most important technique in molecular biology.","Franklin''s research focused exclusively on the structure of DNA."]'::jsonb, 1, 'The text emphasizes that Franklin''s work was essential to the discovery of the DNA double helix while noting she was overshadowed, making the main idea that her contributions were vital but underappreciated.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'ffdb5b08638bf47d5093b6b3e132a84320b09420c1c9b264deddcf8c2dac4291') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-d0c70726-ad03-4110-a2a7-05e1e4dfbac7', 'rw', 'Central Ideas', 'Researchers conducted an experiment in which participants learned a list of words and were then either allowed to sleep or kept awake. The next day, those who slept recalled significantly more words than those who stayed awake. This suggests that sleep plays a crucial role in strengthening newly formed memories.', 'Which choice best states the main idea of the text?', '["Sleep strengthens newly formed memories.","Memory consolidation is impossible without sleep.","Participants who slept recalled more words than those who stayed awake.","The experiment involved learning a list of words."]'::jsonb, 0, 'The passage concludes that sleep plays a crucial role in strengthening newly formed memories, which is directly paraphrased in the correct choice. The other options either state a specific detail from the experiment or make an unsupported claim that memory consolidation is impossible without sleep.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '81a25f7ea4b09f97dbe3b0bcbc0014966e60dbdbe056c3859900040491c36123') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-8c96e5ad-5a1d-491a-a70c-8b1dc135cbdf', 'rw', 'Central Ideas', 'The invention of the printing press in the mid-15th century revolutionized the spread of information. Before its invention, books were painstakingly copied by hand, making them rare and expensive. The printing press enabled mass production of texts, drastically reducing costs and increasing availability. As a result, literacy rates rose across Europe, and ideas spread more rapidly than ever before.', 'Which choice best states the main idea of the text?', '["The printing press increased literacy rates and accelerated the spread of ideas.","The printing press was invented in the mid-15th century.","Before the printing press, books were rare and expensive.","Mass production of texts reduced the cost of books."]'::jsonb, 0, 'The text explains that the printing press made books cheaper and more available, leading to higher literacy and faster exchange of ideas, which is the central idea captured by the correct choice. The other options present isolated details rather than the overarching point.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '3c68b8d3dcd780b9b436bcb7d3a7f84ab6bb97a8d3509b5181cdf59f6ee2d4d1') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-c69dd926-bdc1-491a-94a1-54229d6569ad', 'rw', 'Central Ideas', 'During the late Bronze Age, many societies shifted from using bronze to iron for tools and weapons. Bronze, an alloy of copper and tin, required access to two metals that were rarely found near each other, making long-distance trade essential. Iron ore, by contrast, was abundant and widely distributed. As trade networks became disrupted, iron offered a more reliable and locally available alternative, leading to its gradual adoption despite the greater skill needed to work it.', 'Which choice best states the main idea of the passage?', '["Iron replaced bronze primarily because it was easier to obtain and less dependent on fragile trade routes.","Bronze was a superior material for tools and weapons but required extensive trade networks.","The disruption of trade networks caused the collapse of Bronze Age civilizations.","Working with iron demanded more advanced metallurgical techniques than working with bronze."]'::jsonb, 0, 'The passage explains that iron was adopted because its ore was abundant and locally available, reducing reliance on long-distance trade. The correct choice captures this central reason for the shift, while the other options highlight supporting details or unrelated claims.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '79b039a8cfd40e8272e7bafba9515cb130c9f217a360ef43aa50869f511fcab9') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-2787f98f-ca87-4b03-9885-16f7ff02b7b0', 'rw', 'Central Ideas', 'A longitudinal study tracked the mental health of over 10,000 city residents and found that those living within a ten-minute walk of a park reported significantly lower stress levels than those without such access, even after accounting for income and employment. The effect was strongest in densely populated neighborhoods. The researchers propose that green spaces offer a restorative environment that reduces the cognitive fatigue associated with urban living.', 'Which choice best states the central idea of the text?', '["Urban living inevitably leads to cognitive fatigue.","Income and employment are the main determinants of stress in cities.","Proximity to parks is linked to lower stress, likely because green spaces provide mental restoration.","High population density increases stress regardless of access to parks."]'::jsonb, 2, 'The text reports a study finding that living near a park correlates with lower stress, and the researchers hypothesize that green spaces offer restorative benefits. The correct choice directly reflects this link and the proposed explanation, while the other options either overstate, contradict, or misrepresent the study''s conclusions.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '2705dd692202b66747f07a88a6a5a768d24d2a8fb7999580fe7ccbf801102fff') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-a02f3e11-4588-4703-929d-e8ccd107552d', 'rw', 'Central Ideas', 'Archaeologists excavating a cave in central Europe unearthed stone tools dating to approximately 45,000 years ago. The tools exhibit a distinctive flaking technique previously associated only with Neanderthals, yet the site also contains anatomically modern human remains. This discovery suggests that modern humans either adopted Neanderthal toolmaking methods or that the two groups interacted more extensively than previously believed.', 'Which choice best states the main idea of the text?', '["The tools were made by Neanderthals who later evolved into modern humans.","The find indicates that modern humans and Neanderthals may have shared technological knowledge.","The site is the earliest known evidence of modern human settlement in Europe.","The tools prove that Neanderthals were more innovative than previously thought."]'::jsonb, 1, 'The passage emphasizes that the discovery of tools with Neanderthal techniques alongside modern human remains suggests cultural exchange or adoption. The correct choice captures this idea of shared technological knowledge, while the other options either misrepresent the relationship between the groups or focus on secondary details.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '7d6a91aae66f71ff8a1fc1c2caa72ea8baf9c7384ae7d706943db62607c18a28') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-1f05db57-5e83-4c18-b83b-31e31241f3a2', 'rw', 'Central Ideas', 'A recent study examined the effects of urban green spaces on residents'' mental health. Researchers found that access to parks and community gardens was associated with lower levels of reported stress and anxiety. Interestingly, the benefits were not solely due to increased physical activity; simply having a view of greenery from one''s window also correlated with improved mood. The findings suggest that incorporating vegetation into city planning could be a cost-effective public health strategy.', 'Which choice best states the main idea of the text?', '["Urban green spaces reduce stress only by encouraging physical exercise.","The study proves that planting trees is the most effective way to improve public health.","Access to green spaces in cities is linked to better mental health, likely through multiple mechanisms.","City planners should prioritize building more parks over other infrastructure projects."]'::jsonb, 2, 'The passage reports that green spaces are associated with lower stress and anxiety, and that the benefits extend beyond physical activity to include simply viewing greenery. The main idea is that urban green spaces are linked to improved mental health through various pathways.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '665a420e599f4a4b291246f8af2ad5aae5cde8dafd311f44bfa8f380b388711e') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-c1441de7-5012-48fa-9f08-5e4d9f5a8612', 'rw', 'Central Ideas', 'In the seventeenth century, many natural philosophers still pursued the transmutation of base metals into gold, a goal inherited from medieval alchemy. However, a growing number of experimenters began to emphasize precise measurement and reproducible results. Figures like Robert Boyle argued that chemical phenomena should be explained through mechanical principles rather than mystical ones. By the end of the century, the empirical approach had largely displaced alchemical practices, paving the way for modern chemistry.', 'Which choice best states the main idea of the text?', '["Robert Boyle single-handedly ended the practice of alchemy in the seventeenth century.","The pursuit of transmutation remained the dominant focus of seventeenth-century natural philosophers.","The seventeenth century witnessed a gradual shift from mystical alchemy to empirical chemistry.","Medieval alchemy was completely abandoned at the start of the seventeenth century."]'::jsonb, 2, 'The passage describes how alchemical goals persisted but were increasingly replaced by empirical methods, culminating in the displacement of alchemy by the end of the century. The main idea is that the period saw a gradual transition from alchemy to modern chemistry.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '834544fb788a7ba9d6521e544156f97523f901c9c881ce63b0ad6826c401bd8a') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-cb2c4546-6f02-41d7-8955-b542ae20b3b0', 'rw', 'Central Ideas', 'Although often remembered as a ruthless conqueror, Genghis Khan implemented policies that promoted religious tolerance and meritocracy within his empire. He exempted clergy from taxation and recruited talented individuals regardless of their ethnic or social background. These measures fostered loyalty and administrative stability, enabling the Mongols to govern a vast and culturally diverse territory effectively.', 'Which choice best states the main idea of the text?', '["Genghis Khan''s reputation as a ruthless conqueror is largely undeserved.","The Mongol Empire''s military strength was the primary reason for its stability.","Genghis Khan''s policies of tolerance and meritocracy were key to maintaining stability in his diverse empire.","The vastness of the Mongol Empire made it difficult to govern effectively."]'::jsonb, 2, 'The passage contrasts Genghis Khan''s ruthless image with his administrative policies, noting that religious tolerance and meritocracy fostered loyalty and stability. The correct choice captures this central idea that these policies were crucial to the empire''s success.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'bb30a131ca1d81037940abd9ced6ff6be409c4c21b3411a7db29a22bd080c633') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-eecd3202-2184-4d1f-b40f-4900b09189d0', 'rw', 'Central Ideas', 'Recent studies indicate that sleep plays a far more active role in memory consolidation than previously assumed. During slow-wave sleep, the brain replays neural patterns associated with newly learned tasks, but this replay is not a simple repetition. Instead, the brain reorganizes and integrates new information with existing knowledge, a process that researchers believe underlies the enhancement of creative problem-solving observed after sleep.', 'Which choice best states the main idea of the text?', '["Sleep primarily serves to passively store new memories.","The brain''s replay of neural activity during sleep is a straightforward repetition of daytime experiences.","Sleep actively reorganizes and integrates new information, which may boost creative problem-solving.","Only slow-wave sleep contributes to memory consolidation."]'::jsonb, 2, 'The passage emphasizes that sleep is not a passive process but actively reorganizes and integrates new information, and it links this to enhanced creative problem-solving. The correct choice captures this active role and its potential benefit.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'd922f7bb4dfba46a227804f456086a1a1b0c3153aaa8986850e790c3ffb7ba21') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-c76927ca-05d0-4481-8275-4ed4ab3adaff', 'rw', 'Central Ideas', 'In forest ecosystems, trees are often viewed as solitary competitors for sunlight and nutrients. However, beneath the soil, a vast network of fungi connects the roots of different trees, facilitating the transfer of water, carbon, and other nutrients. This mycorrhizal network can even allow older ''hub'' trees to support shaded seedlings by shunting resources to them. While the extent and ecological significance of these networks are still debated, the evidence suggests that forests function less as collections of isolated individuals and more as interconnected communities.', 'Which choice best states the main idea of the text?', '["Mycorrhizal fungi are the sole source of nutrients for all trees in a forest ecosystem.","The traditional view of trees as solitary competitors has been completely disproven by recent discoveries.","Underground fungal networks enable resource sharing among trees, indicating that forests function as interconnected communities.","Older trees deliberately nurture seedlings through fungal networks, demonstrating altruistic behavior."]'::jsonb, 2, 'The passage contrasts the traditional view of trees as isolated competitors with evidence of resource sharing via mycorrhizal networks, concluding that forests are more like interconnected communities. The correct choice captures this central idea by stating that underground fungal networks enable resource sharing, indicating forests function as interconnected communities.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '2ea57992180f085312c968a780dea8383e2303e49bb04043ceb4232c2490a169') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-c3694a96-e104-4815-a974-785e0594acc4', 'rw', 'Central Ideas', 'For centuries, the period between the fall of Rome and the Renaissance was commonly labeled the ''Dark Ages,'' a term that implied cultural and intellectual stagnation. However, recent scholarship has complicated this picture, revealing a vibrant era of manuscript production, architectural innovation, and the founding of universities. While political fragmentation and economic contraction were real, the label obscures the dynamic intellectual and cultural achievements of the time. Consequently, many historians now regard the term ''Dark Ages'' as a misleading oversimplification.', 'Which choice best states the main idea of the text?', '["The early medieval period was defined by political fragmentation and economic decline, which justify the label ''Dark Ages.''","The term ''Dark Ages'' originally referred to the scarcity of written records, not to cultural backwardness.","Recent scholarship has revealed that the early medieval period was a time of significant cultural and intellectual activity, challenging the traditional ''Dark Ages'' label.","The establishment of universities and manuscript production were the only notable achievements of the early medieval period."]'::jsonb, 2, 'The passage argues that the traditional ''Dark Ages'' label is misleading because recent research has uncovered a period of cultural and intellectual vitality. The correct choice captures this central idea by stating that the period was marked by significant cultural and intellectual activity, which challenges the old label.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '738651937fe04b10ae437cf0402aa6e14d6fe517de24395b386c63424d20a165') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-0be381c8-22ad-4fc2-837d-8d7476f35bd7', 'rw', 'Central Ideas', 'A well-known experiment in behavioral economics presented participants with a choice between a certain gain of $50 and a 50% chance to win $100; most chose the certain gain, displaying risk aversion. When the same participants were offered a certain loss of $50 versus a 50% chance to lose $100, they overwhelmingly preferred the gamble, exhibiting risk-seeking behavior. This asymmetry, termed loss aversion, indicates that losses are psychologically about twice as powerful as gains, challenging the traditional economic assumption that individuals always act in a rationally self-interested manner.', 'Which choice best states the main idea of the text?', '["People consistently prefer guaranteed outcomes over risky ones, regardless of whether the outcomes involve gains or losses.","The experiment reveals that individuals are risk-averse for gains but risk-seeking for losses, a pattern that contradicts the model of purely rational decision-making.","Traditional economic models correctly predict that people will avoid risk in all financial decisions.","Loss aversion demonstrates that people are incapable of making sound financial choices."]'::jsonb, 1, 'The passage describes an experiment showing that participants'' risk preferences reversed depending on whether outcomes were framed as gains or losses. This asymmetry, known as loss aversion, challenges the assumption of rational self-interest. The correct choice accurately summarizes this finding and its implication.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '419c476fd5904bd4e396c8456cda2d81ac79442c1d11844db98ede455778cc74') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-d40181cf-b91c-46d7-9ded-a2ff471d75c4', 'rw', 'Central Ideas', 'In the early twentieth century, many historians attributed the decline of the Roman Empire to moral decay, pointing to the erosion of civic virtue and the spread of luxury. Later scholars shifted the focus to economic factors, such as inflation, the collapse of trade networks, and overreliance on slave labor. More recent research, however, argues that no single cause can explain the empire''s fall; instead, a combination of internal administrative inefficiency, military overextension, and external pressures from migrating tribes gradually undermined imperial cohesion.', 'Which choice best states the main idea of the text?', '["The Roman Empire fell primarily because its citizens abandoned traditional values in favor of decadence.","Economic instability, including inflation and trade collapse, was the main reason for the empire''s decline.","The fall of the Roman Empire resulted from a complex interplay of administrative, military, and external factors rather than a single cause.","The empire''s collapse was inevitable once migrating tribes began to pressure its borders."]'::jsonb, 2, 'The passage traces a shift from single-cause explanations (moral decay, then economic factors) to a more recent view that the fall resulted from a combination of internal administrative inefficiency, military overextension, and external pressures. The correct choice captures this nuanced, multi-causal interpretation.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '26bce2c7f8f8a3ca3c763115f4d055a55198ffe6306bc06e52afe4b40e7a57d0') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-b366289d-d7be-4bf1-a940-14fad552bc07', 'rw', 'Central Ideas', 'A growing body of research has examined the relationship between urban green spaces and residents'' mental health, but findings have been inconsistent. A recent longitudinal study tracked over 10,000 participants and found that living near parks with dense tree canopy was associated with lower levels of anxiety, while proximity to open grassy areas showed no such benefit. Conversely, access to grassy spaces was linked to reduced depressive symptoms, an effect not observed for tree-covered areas. The researchers caution that simply increasing the total amount of green space may not yield uniform mental health improvements; instead, the type of vegetation and the specific mental health outcome must be considered.', 'Which choice best states the main idea of the text?', '["Urban green spaces universally improve mental health by reducing both anxiety and depression.","The mental health benefits of urban green spaces depend on the type of vegetation and the particular mental health condition being addressed.","Tree canopy is the only form of urban greenery that has been shown to reduce anxiety in residents.","The study found no consistent link between green spaces and mental health, contradicting earlier research."]'::jsonb, 1, 'The passage describes a study showing that tree canopy reduces anxiety but not depression, while grassy areas reduce depression but not anxiety. The main idea is that the relationship is nuanced: benefits depend on vegetation type and the specific mental health outcome. The correct choice captures this complexity. The other choices either overgeneralize (universal improvement), overstate a single finding (only tree canopy reduces anxiety), or incorrectly claim no link was found.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'a3ed50ac9c30f4037ef776df4a132a419647d90e6a9db6db8564afffa6d95392') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-465ed6db-f4b0-4608-8226-cc9acb2b8bfd', 'rw', 'Central Ideas', 'For decades, the early Middle Ages in Europe were characterized as the ''Dark Ages,'' a period of cultural and intellectual stagnation following the fall of Rome. However, recent scholarship has complicated this picture by documenting the vibrant manuscript production, cross-cultural trade networks, and scientific inquiry that flourished in monastic and courtly settings. Far from being a monolithic era of decline, the centuries between 500 and 1000 CE witnessed dynamic exchanges of knowledge among Christian, Islamic, and Jewish scholars, as well as significant technological innovations such as the heavy plow and the three-field system. These findings suggest that the traditional label obscures more than it reveals.', 'Which choice best states the main idea of the text?', '["The early Middle Ages were a time of unprecedented scientific discovery that surpassed the achievements of the Roman Empire.","Historians now agree that the term ''Dark Ages'' is entirely inaccurate and should be abandoned.","Recent research indicates that the early Middle Ages were not a uniform period of decline but rather a time of significant cultural and intellectual activity.","The heavy plow and three-field system were the most important technological advances of the early Middle Ages."]'::jsonb, 2, 'The passage contrasts the traditional view of the early Middle Ages as a ''Dark Age'' with recent scholarship that reveals vibrant cultural and intellectual activity. The correct choice captures this central idea: the era was not uniformly stagnant but featured dynamic exchanges and innovations. The other choices either overstate the case (unprecedented discovery, total inaccuracy of the label) or focus on a minor detail (specific technologies) rather than the main argument.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'b1cfb798428ebcd50566517a43bab31efaa325767873a3e6334d9f9f96d999e9') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-e15d7cb7-24ed-472a-9d41-7f2528a2e979', 'rw', 'Command of Evidence', 'A historian claims that the ancient city of Petra was a major trading hub due to its strategic location along incense routes. The historian points to the city''s elaborate water management system as evidence of its wealth and importance.', 'Which finding, if true, would most directly support the historian''s claim about Petra''s role as a trading hub?', '["Petra''s water system was capable of supporting a population of 30,000 people.","Archaeologists have uncovered numerous inscriptions in Petra written in languages from distant regions.","The city''s architecture shows a blend of Nabataean and Greco-Roman styles.","Petra was largely abandoned after a series of earthquakes in the fourth century CE."]'::jsonb, 1, 'The correct choice is ''Archaeologists have uncovered numerous inscriptions in Petra written in languages from distant regions.'' This finding provides direct evidence of contact with far-off peoples, which strongly supports the claim that Petra was a major trading hub. The other choices, while related to Petra''s history, do not directly demonstrate its role in trade.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '68cfbfccc1892c7c138fa5b3e05f8e5b95768e436da86fc259975ffd21395429') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-e7eaf95e-d0e6-4c9d-a498-9dd79780dfbb', 'rw', 'Command of Evidence', 'The city of Greenfield implemented a new curbside recycling program in 2022, providing every household with a recycling bin and launching an educational campaign. City officials claimed the program would significantly increase recycling rates.', 'Which finding, if true, would most directly support the claim that the recycling program was effective?', '["The amount of material recycled in Greenfield increased by 30% in the year after the program began.","The program cost less per household than similar programs in neighboring cities.","Surveys showed that most residents found the educational materials easy to understand.","The total amount of waste sent to landfills decreased slightly over the same period."]'::jsonb, 0, 'A 30% increase in recycled material directly demonstrates that the program achieved its goal of boosting recycling, providing clear evidence of effectiveness.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '9a6f8efccc99705c5aac7deffffc5747492f852c36fde1df28673af84c179f41') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-325f3788-35f2-4853-8348-539252fdc290', 'rw', 'Command of Evidence', 'In a recent study, researchers examined the role of sleep in memory consolidation. Participants were divided into two groups: one group slept for eight hours after learning a list of words, while the other group remained awake. The following day, both groups were tested on their recall. The results showed that the sleep group remembered significantly more words than the awake group. The researchers concluded that sleep plays a critical role in strengthening newly formed memories.', 'Which choice provides the best evidence for the claim that the study found sleep improves memory consolidation?', '["Participants were divided into two groups: one group slept for eight hours after learning a list of words, while the other group remained awake.","The following day, both groups were tested on their recall.","The results showed that the sleep group remembered significantly more words than the awake group.","The researchers concluded that sleep plays a critical role in strengthening newly formed memories."]'::jsonb, 2, 'The sentence ''The results showed that the sleep group remembered significantly more words than the awake group'' directly presents the finding that sleep led to better memory performance, which is the best evidence for the claim. The other choices describe the study design, the testing procedure, or the researchers'' interpretation, but do not present the actual result that supports the claim.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'b3ce239d692ffd5995d3c3041e772de667405788a6c8c93b5183a9d7d8e143dd') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-540eec6d-2781-4b98-bd66-2e7c73017529', 'rw', 'Command of Evidence', 'Before she became a celebrated novelist, Elena Márquez struggled to make ends meet. She worked multiple low-paying jobs while writing in her spare time, often unable to afford basic necessities. Her first manuscript was rejected by over a dozen publishers. Despite these obstacles, she persevered, and her debut novel eventually won a major literary award.', 'Which choice provides the best evidence that Márquez experienced financial hardship early in her career?', '["Before she became a celebrated novelist, Elena Márquez struggled to make ends meet.","She worked multiple low-paying jobs while writing in her spare time, often unable to afford basic necessities.","Her first manuscript was rejected by over a dozen publishers.","Despite these obstacles, she persevered, and her debut novel eventually won a major literary award."]'::jsonb, 1, 'The sentence ''She worked multiple low-paying jobs while writing in her spare time, often unable to afford basic necessities'' directly describes financial hardship by mentioning low-paying work and the inability to afford basic necessities. The other choices refer to a general struggle, rejection by publishers, or eventual success, but do not specifically indicate financial difficulty.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '10747640a5899fff081902a08f3de654eb0668d868d74da5d7ff0efd78671a96') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-c6e447fa-884f-45d9-9c3b-b847545a7314', 'rw', 'Command of Evidence', 'The researcher''s latest paper presents a wealth of data that challenges the long-held assumption that the species is solitary, documenting numerous instances of cooperative behavior.', 'Which choice best completes the text?', '["wealth","dearth","summary","rejection"]'::jsonb, 0, 'The paper ''challenges the long-held assumption'' by ''documenting numerous instances,'' so it must contain a large amount of data. ''Wealth'' means an abundance, which fits the context. ''Dearth'' means a scarcity, which would not support a challenge. ''Summary'' and ''rejection'' do not logically connect to documenting many instances.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'fba9385274a7091f033360bc5aca5afac67d310df3294fe2a72234725ab54606') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-11e4b6e2-1ec9-499d-afd5-cd97d7360708', 'rw', 'Command of Evidence', 'The historian argued that the treaty was not a genuine peace agreement but rather a truce, merely postponing the inevitable conflict.', 'Which choice best completes the text?', '["truce","victory","surrender","celebration"]'::jsonb, 0, 'The phrase ''merely postponing the inevitable conflict'' indicates a temporary pause in hostilities, which is precisely what a truce is. The other choices do not convey a temporary delay of conflict.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '88679357fbbcc2d3129b6e2636f89c64f05fd15496f86ce5ce28dce73ccc9564') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-8a00cca4-b83e-4085-bc27-9eee2e8cd15e', 'rw', 'Command of Evidence', 'Historians continue to debate the primary causes of the Roman Empire''s decline. Some scholars argue that economic factors, such as rampant inflation and the collapse of trade networks, were the central reasons for the empire''s fall. They point to the debasement of currency and the erosion of the tax base as critical evidence. Other historians emphasize military defeats and internal political instability as more decisive.', 'Which choice best supports the claim that economic factors were the main cause of the Roman Empire''s decline?', '["Roman coins from the later empire show a drastic reduction in silver content, indicating severe inflation.","The Roman army suffered a catastrophic defeat at the Battle of Adrianople in 378 CE.","A series of political assassinations and civil wars destabilized the imperial government during the third century.","Germanic tribes crossed the Rhine River in 406 CE, overwhelming Roman border defenses."]'::jsonb, 0, 'The correct choice provides direct evidence of currency debasement and inflation, which are economic factors cited by historians who argue that economic decline caused the fall of Rome. The other choices describe military or political events that do not directly support the economic explanation.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'd7cedd1599585282b671f30149bd8e473db9575bdd086c87cc44ed8f578b78e1') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-e4391a44-bc6f-4602-b2ee-641cfbe00fcd', 'rw', 'Command of Evidence', 'Researchers studying the impact of urban green spaces on mental health hypothesized that regular exposure to parks and gardens reduces stress. In an initial study, they surveyed 500 city residents about their access to green spaces and measured their salivary cortisol levels. The data revealed a modest negative correlation, but the researchers acknowledged that other factors, such as income and exercise habits, could not be ruled out as alternative explanations.', 'Which finding, if true, would most directly support the researchers'' hypothesis?', '["A randomized controlled trial in which participants assigned to apartments with views of greenery show significantly lower cortisol levels than those without such views.","A survey indicating that people who visit parks at least once a week report higher overall happiness.","A study showing that cities with more parks per capita have lower average blood pressure.","A longitudinal study finding that residents who move to greener neighborhoods experience no change in stress levels."]'::jsonb, 0, 'The correct choice describes a randomized experiment that controls for confounding variables and directly tests the causal effect of green space exposure on a physiological stress marker, providing the strongest support for the hypothesis. The other choices rely on correlational data or fail to show a stress-reducing effect.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '4963e1f37945186589a408ab1b8e28c9fcb5f24f01f0e8f0348da75a11ec829a') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-a54a6240-8348-41a3-b1c1-57081ac5bdc4', 'rw', 'Command of Evidence', 'Researchers investigated the effect of sleep on memory consolidation by having participants learn a list of word pairs. One group slept for eight hours after learning, while the other remained awake. The next day, the sleep group recalled an average of 85% of the pairs, compared to 60% for the wake group. Statistical analysis yielded a p-value of 0.003, indicating that the observed difference was highly unlikely to have occurred by random variation. The researchers concluded that sleep facilitates the strengthening of newly formed memories.', 'Which quotation from the passage most directly supports the claim that the study''s results are statistically significant?', '["participants learn a list of word pairs","the sleep group recalled an average of 85% of the pairs, compared to 60% for the wake group","Statistical analysis yielded a p-value of 0.003, indicating that the observed difference was highly unlikely to have occurred by random variation","The researchers concluded that sleep facilitates the strengthening of newly formed memories"]'::jsonb, 2, 'Statistical significance is directly indicated by the p-value and the statement that the difference was highly unlikely to be due to random variation. The other choices describe the task, the raw recall percentages, or the researchers'' conclusion, none of which provide direct evidence of statistical significance.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '171d288a7eda7ea58a86d06caff506a06cba1c0ff148b5b268f672ee9ed1a07d') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-cb4106ec-2e65-42e3-9f6e-dae75e781899', 'rw', 'Command of Evidence', 'Some historians argue that the ancient city of Teotihuacan, known for its massive pyramids, was primarily a commercial hub rather than merely a ceremonial center. They point to the city''s large population and its strategic location in the Valley of Mexico as factors that would have facilitated extensive trade networks.', 'Which finding, if true, would most directly support the historians'' claim?', '["Excavations of residential compounds reveal a high concentration of workshops producing obsidian tools and ceramic goods far beyond local needs.","The city''s main avenue is aligned with the setting sun on certain dates, suggesting a sophisticated astronomical knowledge.","Murals within the pyramids depict deities associated with agriculture and rain, indicating the importance of ritual to the city''s inhabitants.","Archaeologists have uncovered numerous burial sites containing offerings of jade and shell, materials not native to the region."]'::jsonb, 0, 'The correct choice provides direct evidence of large-scale production of goods, which implies a commercial economy geared toward trade rather than purely ceremonial activities. The other choices emphasize religious, astronomical, or ritual aspects, or merely show the presence of non-local materials without indicating the scale or purpose of exchange.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '3c520cbe3636d3ef3b99bf5547b6e6fab33a2a6625cb423cf85c58fcef58e91a') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-e434cad5-6b74-47f7-b066-fda5ec6d69d3', 'rw', 'Command of Evidence', 'In the novel, the garden is initially described as ''lush and overgrown.'' Later, it becomes ''parched and brittle,'' mirroring the protagonist''s increasing despair. By the end, the garden is ''a barren patch of cracked earth.''', 'Which choice best supports the claim that the garden''s condition reflects the protagonist''s mental state?', '["the garden is initially described as ''lush and overgrown''","it becomes ''parched and brittle,'' mirroring the protagonist''s increasing despair","the garden is ''a barren patch of cracked earth''","the protagonist''s increasing despair"]'::jsonb, 1, 'The correct choice explicitly states that the garden''s condition is "mirroring the protagonist''s increasing despair," directly linking the physical state of the garden to her mental state. The other choices either describe the garden without making that connection or refer only to the protagonist''s despair.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '92c085af31e147a52468a693123c4863aacdb106d0f5ccda086350ca44b9f7a7') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-3deee05a-0336-4bf6-a1ec-9b7f1b9f3759', 'rw', 'Command of Evidence', 'A team of psychologists hypothesized that exposure to natural environments improves short-term memory. In an initial study, participants who took a 10-minute walk in a park performed better on a subsequent word-recall task than those who walked along a busy city street. However, the park walkers also reported being in a better mood, which could independently enhance memory. To strengthen the causal claim, the researchers designed a follow-up experiment in which participants viewed images of either natural or urban scenes while their mood was carefully monitored and held constant.', 'Which finding from the follow-up experiment, if true, would most directly support the hypothesis that exposure to nature itself improves short-term memory?', '["Participants who viewed natural scenes reported feeling significantly happier than those who viewed urban scenes.","Participants who viewed natural scenes recalled more words than those who viewed urban scenes, even though mood ratings did not differ between the two groups.","Participants who viewed urban scenes showed no improvement in memory compared to a control group that viewed a blank screen.","The memory advantage for natural scenes disappeared when participants were tested again after a 24-hour delay."]'::jsonb, 1, 'The correct choice shows that memory improvement occurred when participants were exposed to natural scenes while mood was held constant, directly supporting the claim that nature exposure itself—rather than mood—enhances short-term memory. The other choices either confirm a mood difference, compare urban scenes to a blank screen rather than to nature, or describe the duration of the effect, none of which isolate nature exposure as the causal factor.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '23739667920b5418f295056aa6a82295341698d2eda587a3cb0538c123a02a5f') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-d78e5933-5222-4c91-8b61-f5578c670398', 'rw', 'Command of Evidence', 'Historian Maria Torres notes that while the 18th-century explorer Jean-Baptiste Le Moyne publicly advocated for peaceful coexistence with Indigenous peoples, his private journals reveal a disparaging attitude, replete with derogatory remarks and justifications for forced relocation.', 'Which choice best completes the text?', '["disparaging","conciliatory","ambivalent","pragmatic"]'::jsonb, 0, 'The passage contrasts Le Moyne''s public advocacy for peace with his private journals, which contain derogatory remarks and justifications for forced relocation. This evidence indicates a negative, scornful attitude, making ''disparaging'' the correct choice.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'ad58717d5cec8531b4637a48db090e87d3639d94c5ad57ce3613d336063a4e04') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-39f7fd84-a881-468e-9412-8644e7017ec8', 'rw', 'Command of Evidence', 'A team of ecologists studying the impact of invasive cane toads in Australia expected that native red-bellied black snakes would suffer severe population declines due to the toads'' toxicity. However, long-term monitoring revealed that snake populations in toad-invaded areas actually stabilized, likely because the snakes rapidly learned to avoid the toxic prey.', 'Which choice best completes the text?', '["stabilized","plummeted","fluctuated unpredictably","dwindled"]'::jsonb, 0, 'The passage sets up a contrast: ecologists expected severe declines, but the snakes learned to avoid the toxic toads. This suggests the population did not crash; instead, it remained steady. ''Stabilized'' is the only choice consistent with the evidence of learned avoidance preventing decline.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'c0a579f7a594a9adad3085b71d304215e33f72f83f3939b6cd99518fce7ed71a') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-707a387c-2269-4108-84da-d4cb036c3c76', 'rw', 'Command of Evidence', 'A pharmaceutical company has developed neuroclease, a drug designed to reduce beta-amyloid plaques in the brain. In an 18-month randomized controlled trial with early-stage Alzheimer''s patients, researchers measured cognitive function, daily living skills, and brain amyloid levels using PET scans.', 'Which finding from the trial would most directly support the claim that neuroclease slows the underlying disease process rather than merely alleviating symptoms?', '["Patients receiving neuroclease performed significantly better on a delayed recall memory test than those receiving placebo.","Neuroclease treatment led to a statistically significant reduction in amyloid plaque burden compared to placebo.","Caregivers reported that patients on neuroclease showed improved ability to manage daily activities independently.","The frequency of adverse events was similar between the neuroclease and placebo groups."]'::jsonb, 1, 'A reduction in amyloid plaque burden is a direct measure of the disease pathology, indicating that the drug slows the underlying disease process. Improvements in memory test scores and daily activities could result from symptomatic relief without altering disease progression. Similar adverse event rates only demonstrate safety, not efficacy. Therefore, the finding of reduced amyloid burden provides the strongest support for the claim.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'c290f6040c28bd16bf72a3e866b02d0a9110ddc2324eb8a676f028a207da374f') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-18425098-9d4e-45d6-9980-6b793cda9346', 'rw', 'Command of Evidence', 'Scholars continue to debate the primary cause of the Classic Maya collapse. Some emphasize prolonged drought, while others point to deforestation and soil degradation. Lake sediment cores and speleothem records from the Maya lowlands have yielded conflicting interpretations, leaving the relative importance of these factors unresolved.', 'Which choice provides the strongest evidence that drought, rather than deforestation, was the main driver of the collapse?', '["Pollen analysis from a lake near a major Maya center shows a decline in tree pollen and an increase in grass pollen during the collapse period.","Stalagmite growth layers from a cave in the Maya lowlands indicate a severe, multidecadal drought that coincides with the abandonment of urban centers.","Archaeological findings reveal that the Maya constructed extensive water management systems, including reservoirs and canals, to cope with seasonal dry spells.","Deforestation could have reduced evapotranspiration, leading to decreased regional rainfall and exacerbating drought conditions."]'::jsonb, 1, 'The stalagmite data directly documents a severe, prolonged drought at the time of collapse, providing strong evidence that drought was the primary cause. The pollen record (another choice) indicates deforestation, not drought. The water management systems (another choice) suggest the Maya were adapted to dry periods, which could argue against drought as a catastrophic cause. The mechanism linking deforestation to drought (another choice) does not provide direct evidence that drought actually occurred.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '9274bbeb78e3c481d57161a3daa4b5bd5391cae6abe6f11ebc81677130c9b4c5') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-15ac09c3-510c-4189-b588-2cb6e6f79a1d', 'rw', 'Command of Evidence', 'In a classic cognitive dissonance experiment, participants who were paid only $1 to tell a waiting ''participant'' that a boring task was enjoyable later rated the task as more enjoyable than did those paid $20. Festinger and Carlsmith (1959) interpreted this as evidence that insufficient external justification leads individuals to change their internal attitudes to reduce dissonance. Critics, however, argued that the $1 group may have felt greater pressure to comply with the experimenter''s expectations rather than genuinely altering their beliefs. A recent replication attempt found the same pattern, but only when participants believed the experimenter was unaware of the deception, a result that supports the original dissonance explanation.', 'Which choice provides the best evidence for the claim that the original cognitive dissonance interpretation has received empirical support from later research?', '["Participants who were paid only $1 to tell a waiting ''participant'' that a boring task was enjoyable later rated the task as more enjoyable than did those paid $20.","Festinger and Carlsmith (1959) interpreted this as evidence that insufficient external justification leads individuals to change their internal attitudes to reduce dissonance.","Critics, however, argued that the $1 group may have felt more pressure to comply with the experimenter''s expectations rather than genuinely altering their beliefs.","A recent replication attempt found the same pattern, but only when participants believed the experimenter was unaware of the deception, a finding that supports the original dissonance explanation."]'::jsonb, 3, 'The claim that later research supports the original cognitive dissonance interpretation is best evidenced by the sentence describing a recent replication that found the same pattern and explicitly states that this finding supports the original explanation. The other choices present the original finding, the original interpretation, or a criticism, none of which provide evidence of subsequent empirical support.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '4336d6d073855710b44824915aa50f09617f97d38c54fe7bb230370380a7eb16') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-614d9554-21e7-4daa-8063-c8285320e8f1', 'rw', 'Command of Evidence', 'The widespread adoption of the stirrup in medieval Europe is often credited with catalyzing the rise of feudalism. Proponents argue that the stirrup enabled mounted knights to deliver devastating couched-lance charges, making cavalry the dominant military force. To support these expensive warriors, rulers supposedly granted land to vassals in exchange for military service, creating a hierarchical system of land tenure. However, recent scholarship has challenged this view, pointing out that stirrups were in use centuries before feudalism emerged and that the connection between cavalry tactics and land grants is poorly documented. Some historians now contend that the decline of centralized authority, rather than any single technological innovation, was the primary driver of feudal structures.', 'Which quotation from the passage provides the best evidence for the claim that the stirrup theory of feudalism is disputed?', '["The widespread adoption of the stirrup in medieval Europe is often credited with catalyzing the rise of feudalism.","Proponents argue that the stirrup enabled mounted knights to deliver devastating couched-lance charges, making cavalry the dominant military force.","To support these expensive warriors, rulers supposedly granted land to vassals in exchange for military service, creating a hierarchical system of land tenure.","However, recent scholarship has challenged this view, pointing out that stirrups were in use centuries before feudalism emerged and that the connection between cavalry tactics and land grants is poorly documented."]'::jsonb, 3, 'The claim that the stirrup theory is disputed is directly supported by the sentence stating that recent scholarship has challenged the view, noting that stirrups predated feudalism and that the link between cavalry and land grants is not well documented. The other choices merely describe the theory itself without indicating any disagreement.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'e1f498e270dc9dccea8233961e20ffcbe7867b4a9348a0a095bf4e38efa89108') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-f25baff0-f4f6-472a-965e-75e7f3129d5c', 'rw', 'Command of Evidence (Quantitative)', 'A school district introduced a new math curriculum in some of its classrooms while keeping the traditional curriculum in others. The district claims that the new curriculum improves student test scores.', 'Which finding from the study, if true, would most directly support the district''s claim?', '["The mean test score for students using the new curriculum was 78, while the mean score for students using the traditional curriculum was 72.","The mean test score for students using the new curriculum was 72, while the mean score for students using the traditional curriculum was 78.","The new curriculum classrooms had fewer students on average than the traditional classrooms.","Both groups of students had the same teacher."]'::jsonb, 0, 'The finding that students using the new curriculum achieved a higher mean score (78) than those using the traditional curriculum (72) directly supports the claim that the new curriculum improves test scores. The other choices either show the opposite result, point to a confounding variable, or describe a controlled condition that does not itself demonstrate improvement.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'f7b056a0264cd8acc6fa557b756ce764e1c5ad190df04068f164402f87f772e1') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-231b4dc9-711d-472d-9ee5-ac8624a5c661', 'rw', 'Command of Evidence (Quantitative)', 'Researchers tested a new fertilizer on corn crops by applying it to one set of plots and leaving another set untreated. They claim that the new fertilizer increases corn yield.', 'Which finding from the study, if true, would most directly support the researchers'' claim?', '["The average yield for treated plots was 2.4 tons per acre, while the average yield for untreated plots was 2.0 tons per acre.","The average yield for treated plots was 2.0 tons per acre, while the average yield for untreated plots was 2.4 tons per acre.","The total rainfall during the growing season was 12 inches.","The soil pH was the same across all plots."]'::jsonb, 0, 'The finding that treated plots produced a higher average yield (2.4 tons per acre) than untreated plots (2.0 tons per acre) directly supports the claim that the fertilizer increases yield. The other choices either show the opposite result, provide irrelevant weather data, or describe a controlled condition that does not itself demonstrate an increase.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '0e4e0eb978c08a9c7a04477dc94045e96afea26779b9293baf98e2b95a7728e6') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-7f573a58-cefd-419d-ae00-7d085cc237da', 'rw', 'Command of Evidence (Quantitative)', 'A researcher tested a new math teaching method on 100 students. Before the method, the students'' average test score was 65 out of 100. After one semester of using the method, the average score rose to 78. The researcher claims that the new method significantly improves math performance.', 'Which finding, if true, would most directly weaken the researcher''s claim?', '["Students who did not use the method also showed an average increase from 65 to 78 over the same period.","The students reported that they enjoyed the new method more than traditional instruction.","The method was implemented in a school that had recently upgraded its classroom technology.","The average score of 65 before the method was below the national average for similar students."]'::jsonb, 0, 'If students who did not use the method experienced the same improvement, then the increase cannot be attributed to the method, directly weakening the claim that the method caused the improvement.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '2bb854cfd03e575d19f5d99530933b325ed2275e5a1e38a71b51c8782d6b0e6f') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-9d08966b-9f9b-40ec-bbc2-4a890886f090', 'rw', 'Command of Evidence (Quantitative)', 'A researcher claims that a new fertilizer increases tomato yield by at least 20% compared to no fertilizer. In a controlled experiment, tomato plants without fertilizer produced an average of 5.0 kg of tomatoes per plant.', 'Which finding from the experiment would most directly support the researcher''s claim?', '["Plants with the new fertilizer averaged 6.2 kg per plant.","Plants with the new fertilizer averaged 5.8 kg per plant.","Plants with the new fertilizer averaged 5.5 kg per plant.","Plants with the new fertilizer averaged 4.8 kg per plant."]'::jsonb, 0, 'The correct choice shows an average yield of 6.2 kg, which is a 24% increase over the 5.0 kg baseline, exceeding the claimed minimum of 20%.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'ed8defb1915401e1aff356d83014ed3b37c79cfe8d9722d3c02f20eb8930cd23') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-8c1aed8e-93b5-477e-b8ca-abb1b2b8b372', 'rw', 'Command of Evidence (Quantitative)', 'A survey of 500 city residents found that 60% support building a new park. A local official claims that a majority of residents in the city support the park.', 'Which finding from the survey would most directly weaken the official''s claim?', '["The margin of error for the survey is ±5 percentage points.","The survey was conducted only among residents aged 18–35.","55% of respondents who were parents supported the park.","The survey had a response rate of 20%."]'::jsonb, 1, 'The correct choice indicates that the survey sampled only a narrow age group, so the results may not represent the views of all city residents, weakening the claim that a majority of the entire city supports the park.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '67a89c741fb5c0c0b2d304500d208ec023b7c35380ad833ef6d49aca04113a80') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-a2fd2e67-8f16-4ad8-8463-5e1b359ba363', 'rw', 'Command of Evidence (Quantitative)', 'A botanist tested two fertilizers on tomato plants. One group received Fertilizer X, and another group received Fertilizer Y. The botanist claims that Fertilizer X produces taller plants than Fertilizer Y.', 'Which finding, if true, would most directly support the botanist''s claim?', '["The average height of plants given Fertilizer X was 15 cm, while the average height of plants given Fertilizer Y was 12 cm.","The average height of plants given Fertilizer X was 12 cm, while the average height of plants given Fertilizer Y was 15 cm.","The average height of plants given Fertilizer X was 15 cm, and the average height of plants given no fertilizer was 10 cm.","The average height of plants given Fertilizer Y was 12 cm, and the average height of plants given no fertilizer was 10 cm."]'::jsonb, 0, 'The claim asserts that Fertilizer X leads to taller plants than Fertilizer Y. The correct choice provides a direct comparison showing a greater average height for Fertilizer X (15 cm) than for Fertilizer Y (12 cm), which supports the claim.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'aa588aa547c6406ed86986c16cbaf96890b4f5f8e7d93a3b85c460e4ae33ef96') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-c9167c54-7901-4153-8a77-b2595f0f90a3', 'rw', 'Command of Evidence (Quantitative)', 'A researcher hypothesizes that using virtual labs in chemistry courses improves students'' understanding of stoichiometry more than traditional textbook-based instruction. Two classes of students with similar prior chemistry knowledge were assigned to either a virtual lab group or a textbook group. After a four-week unit, the virtual lab group''s average score on a stoichiometry test was 82%, while the textbook group''s average was 76%. The researcher claims that the virtual lab method caused the higher performance.', 'Which finding, if true, would most directly weaken the researcher''s claim?', '["The virtual lab group had significantly higher average scores on a pre-unit stoichiometry test than the textbook group.","The virtual lab group reported enjoying the lessons more than the textbook group.","The textbook group spent more time on homework assignments than the virtual lab group.","The virtual lab group''s post-unit test scores were higher than the textbook group''s pre-unit test scores."]'::jsonb, 0, 'The claim is that the virtual lab method caused the higher post-unit scores. If the virtual lab group already had higher pre-unit scores, then the post-unit difference may be due to pre-existing differences rather than the teaching method, weakening the causal claim. The other choices do not weaken the claim: enjoyment does not address causation; the textbook group spending more time on homework could suggest they worked harder but still scored lower, which might strengthen the claim; and the virtual lab group''s post-unit scores being higher than the textbook group''s pre-unit scores is expected and irrelevant.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'c363263c61d3a4885534f3d8182d959f1d38a88e8529a19d9cc5cf99a2d3de3f') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-51782474-ef72-464c-bbc1-a662784ca844', 'rw', 'Command of Evidence (Quantitative)', 'A study followed 200 adults with high cholesterol who were randomly assigned to either a Mediterranean diet or a low-fat diet. After six months, the Mediterranean diet group had an average decrease in LDL cholesterol of 15 mg/dL, while the low-fat diet group had an average decrease of 10 mg/dL. The researchers claim that the Mediterranean diet is more effective at lowering LDL cholesterol than the low-fat diet.', 'Which finding, if true, would most directly support the researchers'' claim?', '["The Mediterranean diet group also experienced a greater average decrease in HDL cholesterol than the low-fat diet group.","The Mediterranean diet group had a higher average baseline LDL cholesterol level than the low-fat diet group.","The Mediterranean diet group adhered to their assigned diet more strictly than the low-fat diet group.","The difference in LDL cholesterol reduction between the two groups was statistically significant."]'::jsonb, 3, 'The claim is that the Mediterranean diet is more effective at lowering LDL cholesterol. The observed difference of 5 mg/dL could be due to chance. Showing that this difference is statistically significant supports the claim by confirming that the result is reliable and not a random fluctuation. The other choices do not support the claim: a greater decrease in HDL (good cholesterol) would be undesirable; a higher baseline LDL in the Mediterranean group could explain the greater reduction without the diet being more effective; and stricter adherence in the Mediterranean group suggests the difference might be due to adherence rather than the diet itself.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '7a942e26b909121b098ae8e5261512c3d3c709226490401a4228560d7c2bfecb') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-8cd46fde-42bb-4f74-b139-3c5df83df6ba', 'rw', 'Command of Evidence (Quantitative)', 'A study examined whether a new interactive software program improves algebra test scores. One group of students used the software, while another used traditional textbooks. After one semester, the software group had a mean score of 82, compared to 78 for the textbook group, a statistically significant difference (p < 0.05). However, participation in the software group was voluntary, and some researchers argue that more motivated students may have chosen the software.', 'Which finding, if true, would most directly support the claim that the software itself caused the higher scores?', '["The software group had higher average grades in previous math courses than the textbook group.","The software group reported spending more time studying outside of class than the textbook group.","When students were randomly assigned to groups, the software group again scored significantly higher.","The software group rated their lessons as more enjoyable than did the textbook group."]'::jsonb, 2, 'Random assignment eliminates preexisting differences between groups, so the finding that the software group still scored higher when students were randomly assigned directly supports the claim that the software itself caused the improvement, rather than motivation or prior ability. The other findings point to confounding factors (prior grades, study time) or subjective enjoyment, which do not establish causation.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '812b455271990e3e54fb35da9a7e98953937cbef990996a31b624df8f42f0566') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-2139867e-4aa0-4941-bde3-8f2105310e0f', 'rw', 'Command of Evidence (Quantitative)', 'In 2020, the city of Greenfield launched a new recycling program that included curbside pickup and a public awareness campaign. The city''s recycling rate rose from 25% in 2019 to 40% in 2021. During the same period, neighboring Rivertown, which made no changes to its recycling policies, saw its recycling rate increase from 20% to 30%. Some officials claim that Greenfield''s new program was the primary cause of the city''s higher recycling rate.', 'Which finding, if true, would most weaken the claim that Greenfield''s new program was the primary cause of its increased recycling rate?', '["Greenfield''s population grew by 5% between 2019 and 2021, while Rivertown''s population remained stable.","A statewide environmental campaign was launched in 2020 that encouraged recycling in all cities.","Greenfield''s recycling rate in 2021 was still lower than the national average.","Rivertown''s recycling rate had been increasing steadily for several years before 2020."]'::jsonb, 1, 'The statewide campaign provides an alternative explanation for the rise in recycling in both cities, suggesting that the increase in Greenfield may have been due to the campaign rather than the local program. The other findings do not directly challenge the program''s role: population growth does not explain a rate increase, being below the national average is irrelevant, and Rivertown''s prior trend does not account for Greenfield''s change.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '2cfe28781246b8072a07bb7981e5031255efac4717288882876b7b555eb95721') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-686f7721-2a89-409b-afea-9478b75af978', 'rw', 'Command of Evidence (Quantitative)', 'A study compared two groups of 200 students each. The first group used a new interactive math software for one semester; their average test score rose from 72 to 81, and 85% reported increased confidence. The second group used traditional textbooks; their average score rose from 71 to 78, and 60% reported increased confidence. The researchers claim that the interactive software is more effective than traditional textbooks at improving both performance and confidence.', 'Which finding, if true, would most directly weaken the researchers'' claim?', '["The interactive software group contained a significantly higher proportion of students who had previously taken advanced math courses.","The increase in the control group''s average test score was statistically significant.","Students in the interactive software group spent more time studying outside of class than the control group.","The confidence survey for the software group was administered immediately after a particularly engaging lesson."]'::jsonb, 0, 'If the interactive software group had more students with advanced math backgrounds, their higher score gains and confidence could be due to prior knowledge rather than the software itself, weakening the claim that the software caused the improvements.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'f453520295ee98f729e573acdc67b1e8046becb838c8b5bbeb0ee828cb8537b1') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-c462b6c5-21aa-4dc7-8ac6-3e0c0633ac43', 'rw', 'Command of Evidence (Quantitative)', 'A school district introduced a new math curriculum in half of its elementary schools, while the other half continued with the standard curriculum. At the end of the year, students in the new curriculum schools scored an average of 78% on a standardized math test, compared to 72% in the standard curriculum schools. However, the new curriculum schools also had smaller class sizes (average 18 students vs. 24) and more experienced teachers (average 12 years vs. 8 years). The district claims the new curriculum directly caused the higher scores.', 'Which finding, if true, would most weaken the district''s claim?', '["In schools where class sizes were reduced but the standard curriculum was kept, math scores rose to 77%.","The new curriculum required more homework, which some students found stressful.","The standardized test was designed by the same researchers who developed the new curriculum.","Students in the new curriculum schools had higher attendance rates than those in the standard curriculum schools."]'::jsonb, 0, 'The correct choice shows that reducing class size alone, without the new curriculum, produced nearly the same score increase (from 72% to 77%). This suggests that smaller class sizes, not the curriculum, may have caused the original improvement, weakening the district''s claim.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '296d2e143de8d39fe642277a677fcf6d196d5e0573f26c6ed22ae25182db0443') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-dc7e2646-fc50-49c8-87ca-d69b4d967dc3', 'rw', 'Command of Evidence (Quantitative)', 'Researchers studied a new teaching method designed to improve science test scores. They divided students into two groups based on their pre-test scores: those who scored below the median (low initial) and those who scored at or above the median (high initial). Within each group, half the students were taught using the new method and half using traditional instruction. After the course, the researchers found that among low-initial students, those taught with the new method had higher average post-test scores than those taught traditionally. They concluded that the new method improves performance for students who initially struggle.', 'Which finding, if true, would most weaken the support that the study provides for the researchers'' conclusion?', '["Among low-initial students, those taught with the new method had higher pre-test scores on average than those taught traditionally.","Among high-initial students, those taught with the new method had higher post-test scores than those taught traditionally.","The new method group had a higher overall post-test average than the traditional group.","Among low-initial students, the post-test scores were lower than the post-test scores of high-initial students."]'::jsonb, 0, 'The study''s support for the conclusion depends on the assumption that the low-initial students in the new method and traditional groups were comparable before the intervention. If the new method group had higher pre-test scores on average, the observed post-test difference could be due to pre-existing differences rather than the teaching method, weakening the support. The other choices do not address this comparability: the second choice would not weaken a conclusion about low-initial students, the third is too general, and the fourth merely restates an expected pattern.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '0b00fe7deb6aeb92d26d4789f258157095b7224dc383f33f80f92fbdb757846e') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-579c7e5f-5b38-4fe0-8b86-28190aaab9b7', 'rw', 'Command of Evidence (Quantitative)', 'A school compared two algebra teaching methods: Method A used interactive software, while Method B used traditional textbooks. After one semester, the average test score for Method A was 85.2, and for Method B was 80.1. The school claims that interactive software improves algebra performance more than traditional textbooks.', 'Which finding, if true, would most directly weaken the school''s claim?', '["The difference in test scores was statistically significant (p = 0.03).","The test was designed by teachers who had no preference for either method.","Students in Method A had significantly higher average GPAs in previous math courses.","Method A and Method B classes met for the same total number of hours."]'::jsonb, 2, 'The school attributes the higher scores to the interactive software. However, if the Method A students began with significantly stronger math backgrounds, as indicated by higher prior GPAs, that pre-existing advantage could explain their better performance, weakening the causal link between the software and the score difference.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '482c9573b7d4b6c8bae48c37503a1fa599bb2765cc2c5f807af141dcc12f9302') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-3fdd1356-1712-4ae1-935a-7a2bf01901a2', 'rw', 'Command of Evidence (Quantitative)', 'Researchers tested a new fertilizer on corn crops by dividing a field into two sections: one treated with the fertilizer and one untreated. At harvest, the treated section yielded 120 bushels per acre, while the untreated section yielded 100 bushels per acre. The researchers claim that the fertilizer increases corn yield.', 'Which finding, if true, would most directly weaken the researchers'' claim?', '["The difference in yield between the two sections was not statistically significant (p = 0.23).","The treated section was located closer to the researchers'' laboratory than the untreated section.","The corn variety used in both sections was identical.","The study was conducted over a single growing season."]'::jsonb, 0, 'The claim that the fertilizer increases yield rests on the observed 20-bushel difference. If that difference is not statistically significant (p = 0.23), the result is likely due to chance rather than a real effect of the fertilizer, directly undermining the evidence for the claim.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '9cb5e48b94ffa87741169d70366c6fd941d2ad76ac82b17b969843b745c02367') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-551c3a17-931a-45f1-baa0-96cb68492335', 'rw', 'Command of Evidence (Quantitative)', 'A clinical trial tested a new drug for hypertension. Researchers randomly assigned 500 patients to receive either the drug or a placebo. After 12 weeks, the mean reduction in systolic blood pressure was 15.2 mmHg for the drug group and 5.8 mmHg for the placebo group. The researchers concluded that the new drug is effective in lowering blood pressure.', 'Which finding from the study, if true, would most directly support the researchers'' conclusion?', '["The drug group had a higher dropout rate due to side effects than the placebo group.","The placebo group had a mean baseline systolic blood pressure 10 mmHg higher than the drug group.","The reduction in systolic blood pressure in the drug group was consistent across all age subgroups.","The difference in mean reduction between the two groups was statistically significant (p < 0.01)."]'::jsonb, 3, 'Statistical significance at p < 0.01 indicates that the observed difference in blood pressure reduction between the drug and placebo groups is very unlikely to have occurred by chance. This directly supports the conclusion that the drug is effective. A higher dropout rate due to side effects would weaken the case for the drug''s overall benefit. A higher baseline blood pressure in the placebo group could introduce regression to the mean, potentially undermining the comparison. Consistency across age subgroups is a secondary finding that does not directly address whether the overall difference is reliable.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '200860038442da4e039c454dac26aa5a5f402378f8d475ff119db12b35af2b92') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-5eb8cba7-bf18-420f-85d0-a94ea42450ea', 'rw', 'Command of Evidence (Quantitative)', 'A city implemented a new traffic signal timing system on a major avenue, aiming to reduce average travel time during peak hours. Before the change, the average travel time along the avenue during the evening rush hour was 22.4 minutes (SD = 4.1 minutes). After the change, a study measured travel times for 60 randomly selected trips during the same rush hour period and found a mean of 19.2 minutes (SD = 3.5 minutes). The city claims that the new system has reduced average travel time by more than 2 minutes.', 'Which finding from the study, if true, would most directly support the city''s claim?', '["The median travel time after the change was 19.5 minutes.","The standard deviation of travel times after the change was 3.5 minutes.","The 95% confidence interval for the mean travel time after the change was 18.3 to 20.1 minutes.","The number of trips in the sample that took longer than 25 minutes was 4."]'::jsonb, 2, 'The 95% confidence interval for the post-change mean travel time lies entirely below 20.4 minutes (22.4 minus 2). This indicates that the true mean is very likely less than 20.4 minutes, meaning the reduction exceeds 2 minutes, which directly supports the city''s claim.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'd8227497ab044ec696df46e73664141559bd0ad48ad95837de0ea7021c9e530f') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-263a46e5-05aa-4b0f-8dbf-712f67156d34', 'rw', 'Command of Evidence (Quantitative)', 'A study investigated whether a new teaching method improves student performance on a standardized math test. Two groups of 50 students each were taught the same material using either the new method or a traditional method. After the course, the mean test score for the new method group was 78.2 (SD = 9.5), while the mean for the traditional group was 74.1 (SD = 10.2). The researchers claim that the new method substantially improves math test scores.', 'Which finding from the study, if true, would most directly weaken the researchers'' claim?', '["The median score for the new method group was 76, and the median for the traditional group was 75.","The 95% confidence interval for the difference in means (new minus traditional) was 0.5 to 7.7.","The new method group had 5 students who scored above 95, while the traditional group had only 1 such student.","The new method group spent an average of 2.5 more hours per week on homework than the traditional group."]'::jsonb, 3, 'The finding that the new method group spent more time on homework introduces a confounding variable: the observed score difference may be due to extra practice rather than the teaching method itself. This directly weakens the claim that the method is responsible for the improvement.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '02a11d5548fe147b260bef7c10bc2fe30fe7e68ad2631e34903942a56da6cdb6') on conflict (id) do nothing;
