insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-84e808d7-15af-4243-96fd-650bb6056788', 'rw', 'Cross-Text Connections', 'Text 1: The decline of the Mayan civilization in the southern lowlands was primarily driven by a prolonged drought that undermined agricultural productivity. Evidence from lake sediment cores indicates a severe dry period coinciding with the abandonment of major urban centers. While warfare and political fragmentation also occurred, these were likely symptoms of resource scarcity rather than independent causes.
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-206609f4-ebcd-4b12-a3fb-2cfb8a6cbb86', 'rw', 'Cross-Text Connections', 'Text 1: In Shakespeare''s Hamlet, the protagonist''s delay in avenging his father''s murder is best understood as a result of profound moral and philosophical uncertainty. Hamlet''s soliloquies reveal a mind consumed by existential questions about the nature of action, the afterlife, and the legitimacy of revenge, which paralyze his will and prevent him from taking decisive action.
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-40485087-dad9-402c-949f-d1edb65c826a', 'math', 'Circles', null, 'A circle has a diameter of 10. What is its circumference?', '["5π","10π","20π","100π"]'::jsonb, 1, 'The circumference of a circle is π times the diameter. Since the diameter is 10, the circumference is 10π.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '7ec9a0b533ff03df36e900fef496e4a27435757349d1e4d735f3429d3ebbbfcb') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-a18c9982-d786-4535-b97c-3b79979abf28', 'math', 'Circles', null, 'The equation of a circle is (x-3)^2 + (y+4)^2 = 25. What is the radius of the circle?', '["3","4","5","25"]'::jsonb, 2, 'The standard form of a circle''s equation is (x-h)^2 + (y-k)^2 = r^2, where r is the radius. Here r^2 = 25, so the radius r = 5.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'afa8b03670a9ea5e7f98914cc097ef30b156f545079925b941836fec4fd2bb31') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-dc2207ed-7763-402e-9a4e-98fd86ea94ed', 'math', 'Circles', null, 'The diameter of a circle is 12. What is the area of the circle?', '["12π","24π","36π","144π"]'::jsonb, 2, 'The radius is half the diameter, so r = 6. The area is πr² = π(6)² = 36π.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '0f246101e78dec048251f847dcaa5272044208a79d6d2697e628c257a0326398') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-2284f0c0-7a6c-49ca-8782-dda2eb2ddade', 'math', 'Circles', null, 'A circle has a radius of 5. What is its circumference?', '["5π","10π","25π","100π"]'::jsonb, 1, 'The circumference of a circle is given by C = 2πr. With r = 5, C = 2π(5) = 10π.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '3315b57a4a6ca2824e20203d114591c011d3436c4858836efddac289696ed0b7') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-7ae85eed-4699-4e50-a78d-11fa92b72d97', 'math', 'Circles', null, 'A circle has a circumference of 18π inches. What is the radius, in inches?', '[]'::jsonb, 0, 'Circumference formula: C = 2πr. Substitute 18π for C: 18π = 2πr. Divide both sides by 2π: r = 9.', 'ai', true, 'easy', 'model', 'spr', '9', null, null, 'active', 'e09065819e233fba9ffa3ee9966093f7b1a5af89a0787672d793ea0e3eac096b') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-e1fb2d6b-3915-4d52-afd7-8f6da43d113d', 'math', 'Circles', null, 'A circle with center (0,0) passes through the point (6,8). What is the radius of the circle?', '[]'::jsonb, 0, 'The radius is the distance from the center (0,0) to the point (6,8). Use the distance formula: sqrt((6-0)^2 + (8-0)^2) = sqrt(36+64) = sqrt(100) = 10.', 'ai', true, 'easy', 'model', 'spr', '10', null, null, 'active', '8d58e34339b616f729f77e3fc98aac2a67f2428fb8ef61b6f32d86efcbf79bd8') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-ffd94553-f7e8-497b-a0e0-22a17d9f156c', 'math', 'Circles', null, 'A circle has an area of 36π square units. What is the diameter of the circle?', '[]'::jsonb, 0, 'The area of a circle is given by A = πr^2. Set πr^2 = 36π, so r^2 = 36 and r = 6. The diameter is twice the radius, so d = 2(6) = 12.', 'ai', true, 'medium', 'model', 'spr', '12', null, null, 'active', '1bb98d4260f6eef20df0ec8318fd554bc1ede4dc6b8a2b6867128918db0b1f93') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-243dc63b-07eb-4cea-a2ae-98ad0b031099', 'math', 'Circles', null, 'In a circle with radius 10, a chord is 6 units from the center. What is the length of the chord?', '[]'::jsonb, 0, 'Draw a radius to one endpoint of the chord and a perpendicular from the center to the chord. This forms a right triangle with hypotenuse 10 (the radius) and one leg 6 (the distance from the center to the chord). The other leg is half the chord length. By the Pythagorean theorem, half the chord = sqrt(10^2 - 6^2) = sqrt(100 - 36) = sqrt(64) = 8. The full chord length is 2 × 8 = 16.', 'ai', true, 'medium', 'model', 'spr', '16', null, null, 'active', '9a05c24cf0f736062ff8df534819afc0dcbe47900394114e31733ae445c68e78') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-07da8902-f910-46ac-9012-8da53e7b734f', 'math', 'Circles', null, 'A circle has a radius of 6. A central angle of 60° intercepts an arc. What is the length of the arc?', '["2π","4π","6π","12π"]'::jsonb, 0, 'Arc length = (central angle / 360°) * 2πr. Substituting the given values: (60/360) * 2π * 6 = (1/6) * 12π = 2π.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'cd1b43557043fc2e37072bf11ecb3056763b6424f8b044b4a19cf4689ca47d0b') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-cca4adc5-240b-42f8-b664-6e7a9d66c3b8', 'math', 'Circles', null, 'In a circle, a central angle of 72° intercepts an arc of length 4π. What is the radius of the circle?', '[]'::jsonb, 0, 'Arc length = (central angle / 360°) × 2πr. Substitute: 4π = (72/360) × 2πr = (1/5) × 2πr. Cancel π: 4 = (2/5)r. Multiply both sides by 5/2: r = 10.', 'ai', true, 'medium', 'model', 'spr', '10', null, null, 'active', 'b01ad8661e28f9dc0e08ff8c9cc9452afaa9f6257de4ead21cc613241e1d98b9') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-e3573d78-96a0-4054-ae6c-d5189909d3b3', 'math', 'Circles', null, 'A circle has an area of 49π square inches. What is the diameter, in inches, of the circle?', '[]'::jsonb, 0, 'Area = πr^2 = 49π, so r^2 = 49 and r = 7. The diameter is twice the radius: 2 × 7 = 14.', 'ai', true, 'medium', 'model', 'spr', '14', null, null, 'active', '07578d884d4c5d3de1ab5ab662770ae88cbb7c776c90ceae801d94a366b9f01a') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-0a773190-cce1-410f-9149-2323684c1588', 'math', 'Circles', null, 'A circle in the xy-plane has center (2, -1) and passes through the point (5, 3). What is the diameter of the circle?', '["5","10","25","100"]'::jsonb, 1, 'The distance from the center (2, -1) to the point (5, 3) is the radius. Using the distance formula: sqrt((5 - 2)^2 + (3 - (-1))^2) = sqrt(3^2 + 4^2) = sqrt(9 + 16) = sqrt(25) = 5. The diameter is twice the radius, so 2 * 5 = 10.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '5bfc108ebc3b34b9415e2781865fc4b44689e3ed13dfd9e959f6d9fe48c90aed') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-95fb4324-f0dc-4e04-9ad1-df50237b09f4', 'math', 'Circles', null, 'A circle in the first quadrant is tangent to both the x-axis and the y-axis, and also tangent to the line 3x + 4y = 12. What is the radius of the smaller such circle?', '["1","2","3","6"]'::jsonb, 0, 'Because the circle is tangent to both axes, its center is (r, r) and its radius is r. The distance from the center to the line 3x + 4y - 12 = 0 must equal r. Using the point-to-line distance formula: |3r + 4r - 12| / 5 = r → |7r - 12| = 5r. This yields two equations: 7r - 12 = 5r → r = 6, and 7r - 12 = -5r → r = 1. The smaller radius is 1, so the correct choice is ''1''.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '8a026df863b68088e977216d7b0678afb759edfaf071f52c9289556f6ac47a13') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-60da9f2f-16c4-4973-8c18-532f95a862c2', 'math', 'Circles', null, 'What is the shortest distance from the point (7, -2) to the circle given by the equation x^2 + y^2 - 6x + 4y - 12 = 0?', '["1","4","5","9"]'::jsonb, 0, 'Complete the square: (x^2 - 6x + 9) + (y^2 + 4y + 4) = 12 + 9 + 4 → (x - 3)^2 + (y + 2)^2 = 25. The circle has center (3, -2) and radius 5. The distance from (7, -2) to the center is |7 - 3| = 4. Since 4 < 5, the point lies inside the circle. The shortest distance from an interior point to the circle is the radius minus the distance to the center: 5 - 4 = 1. The correct choice is ''1''.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'fefe6035aee9c0d9270978058f87e95eae0dd1d8b27c06d61b91e944426ac86d') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-25550436-85f6-493b-8008-72b00f94ac0a', 'math', 'Circles', null, 'A circle in the xy-plane lies entirely in the second quadrant and is tangent to both the x-axis and the y-axis. The center of the circle lies on the line y = 2x + 1. What is the radius of the circle?', '["1/3","1","2","3"]'::jsonb, 0, 'Since the circle is tangent to both axes and lies in the second quadrant, its center must be at (-r, r) where r > 0 is the radius. The center lies on the line y = 2x + 1, so substitute: r = 2(-r) + 1 => r = -2r + 1 => 3r = 1 => r = 1/3. Thus the radius is 1/3.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'd3f7f27b8414aa917dd7a343b92b29c6c059d6cf08502dc142b9f5a37886aa6e') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-b46a52f9-539b-453b-997c-b377ff6a2639', 'math', 'Circles', null, 'In the xy-plane, the circle given by the equation (x-2)^2 + (y+3)^2 = 25 is reflected across the line y = x. Which of the following is the equation of the reflected circle?', '["(x+3)^2 + (y-2)^2 = 25","(x-2)^2 + (y+3)^2 = 25","(x+2)^2 + (y-3)^2 = 25","(x-3)^2 + (y+2)^2 = 25"]'::jsonb, 0, 'The original circle has center (2, -3) and radius 5. Reflecting across the line y = x swaps the x- and y-coordinates of the center, giving (-3, 2). The radius remains 5. The equation of the reflected circle is (x+3)^2 + (y-2)^2 = 25.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '2553cd9991dc10f14b85d48c552f689897c43880a8356a188d0def288fb03afd') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-ed150f44-9bdb-4c54-a739-2a6b69de7700', 'math', 'Circles', null, 'A circle in the xy-plane has its center on the line y = x - 1 and passes through the points (2, 3) and (8, 3). What is the radius of the circle?', '["√10","3","2","6"]'::jsonb, 0, 'The center of a circle lies on the perpendicular bisector of any chord. The chord connecting (2,3) and (8,3) is horizontal, so its perpendicular bisector is the vertical line x = 5. The center also lies on the line y = x - 1, so substituting x = 5 gives y = 4. Thus the center is (5,4). The radius is the distance from the center to either given point: √((5-2)² + (4-3)²) = √(9+1) = √10. The correct choice is √10. The other choices are common mistakes: 3 comes from using the midpoint (5,3) as the center; 2 comes from intersecting the chord line y=3 with y=x-1 to get (4,3) as the center; 6 is the distance between the two given points, mistaken for the radius.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'd20684ee806064f558f48553754b9f5befdddf0c1cf568379e445041dabf6845') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-b6499792-f4ec-45d8-8027-4cb10bcea890', 'math', 'Circles', null, 'A circle in the xy-plane passes through the points (1, 2), (3, 4), and (5, 2). Which of the following is an equation of the circle?', '["(x - 3)² + (y - 2)² = 4","(x - 3)² + (y - 2)² = 2","(x - 2)² + (y - 3)² = 4","(x - 3)² + (y - 4)² = 4"]'::jsonb, 0, 'The points (1,2) and (5,2) have the same y-coordinate, so the perpendicular bisector of the segment joining them is the vertical line x = 3. Thus the center has x-coordinate 3. Let the center be (3, k). The distance to (1,2) equals the distance to (3,4): (3-1)² + (k-2)² = (3-3)² + (k-4)². This simplifies to 4 + (k-2)² = (k-4)². Expanding: 4 + k² - 4k + 4 = k² - 8k + 16, so k² - 4k + 8 = k² - 8k + 16. Solving gives 4k = 8, so k = 2. The center is (3,2). The radius squared is (3-1)² + (2-2)² = 4. Therefore, the equation is (x - 3)² + (y - 2)² = 4. The correct choice is (x - 3)² + (y - 2)² = 4.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'c3df98eb407f66482625350df0be08ce64b90811cf4f6833a5159e816e950779') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-d2ab649e-1a53-45d0-9054-2dc341f07a3d', 'math', 'Equivalent Expressions', null, 'Which expression is equivalent to 2(x + 3) - (x - 1)?', '["x + 7","x + 5","3x + 5","3x + 7"]'::jsonb, 0, 'Distribute: 2(x + 3) = 2x + 6, and -(x - 1) = -x + 1. Combine like terms: (2x - x) + (6 + 1) = x + 7.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '595c3e752e4fe2ae6eb4a6866bb25406f726a8a008a926dfb72e70882587277a') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-e14e6cf7-e985-405f-973d-83822b59334b', 'math', 'Equivalent Expressions', null, 'Which expression is equivalent to (x + 2)^2?', '["x^2 + 4x + 4","x^2 + 4","x^2 + 2x + 4","x^2 + 4x + 2"]'::jsonb, 0, 'Expand the binomial: (x + 2)^2 = x^2 + 2*x*2 + 2^2 = x^2 + 4x + 4.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'e3030a1c975d18b8904e9d371128d67ed8459e579658f6c3da19b69d7e85c1df') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-32858047-38a2-4e06-bf1f-3c1ba9ba2575', 'math', 'Equivalent Expressions', null, 'Which of the following is equivalent to 2(x + 3) - (x - 2)?', '["x + 8","x + 4","3x + 4","3x + 8"]'::jsonb, 0, 'Distribute the 2: 2x + 6. Distribute the negative sign: -x + 2. Combine like terms: (2x - x) + (6 + 2) = x + 8.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '52ef2831047b529a07f4443d1efd1e324cb9f9541847370129c1788ce51321ac') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-88719bc2-4b75-4334-9717-0e1161060fbb', 'math', 'Equivalent Expressions', null, 'Which expression is equivalent to 4x^2 - 9?', '["(2x - 3)(2x + 3)","(2x - 3)^2","(4x - 3)(x + 3)","(2x + 3)(2x + 3)"]'::jsonb, 0, 'The expression 4x^2 - 9 is a difference of squares: (2x)^2 - 3^2. It factors as (2x - 3)(2x + 3). The correct choice is (2x - 3)(2x + 3).', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '7982c6416702268e29184994278d6be6bcc1328fc43124bf8437566b40172315') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-43fbf754-fa05-479f-8ee3-e9ee64822575', 'math', 'Equivalent Expressions', null, 'If 2(x+3)+3(x-2)=ax+b, what is the value of a?', '[]'::jsonb, 0, 'Expand the left side: 2x+6+3x-6 = 5x+0. So the expression is 5x+0, meaning a=5.', 'ai', true, 'easy', 'model', 'spr', '5', null, null, 'active', '17fa58bb4f7af98d00d9cb762528c41e2fd459e996627d4d6a5412c75c120af1') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-8a44547d-cf2f-4912-9b1b-3865df48506d', 'math', 'Equivalent Expressions', null, 'If (x+4)(x-4)=x^2-c, what is the value of c?', '[]'::jsonb, 0, 'Use the difference of squares: (x+4)(x-4)=x^2-16. Thus c=16.', 'ai', true, 'easy', 'model', 'spr', '16', null, null, 'active', 'c7a21dc769209b07963b8a5f7e1fc5e4300d4446d00d7d62995c84bb07c532df') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-7d9176dd-9cbd-44de-810d-5a2137306cf0', 'math', 'Equivalent Expressions', null, 'If 5(2x - 3) - 2(x + 1) = ax + b for all x, what is the value of a + b?', '[]'::jsonb, 0, 'Simplify the left side: 5(2x - 3) - 2(x + 1) = 10x - 15 - 2x - 2 = 8x - 17. So a = 8, b = -17. Then a + b = 8 + (-17) = -9.', 'ai', true, 'medium', 'model', 'spr', '-9', null, null, 'active', '7d7a82c0fe096953c1bf7389406e1860114967fd7bc5df2bc59db36239c40728') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-027b0cc8-870a-4e02-b470-a4be17cfcfec', 'math', 'Equivalent Expressions', null, 'If (x+4)(2x-3) = 2x^2 + kx - 12 for all values of x, what is the value of k?', '[]'::jsonb, 0, 'Expand the left side: (x+4)(2x-3) = 2x^2 - 3x + 8x - 12 = 2x^2 + 5x - 12. Equating coefficients of x gives k = 5.', 'ai', true, 'medium', 'model', 'spr', '5', null, null, 'active', '7cf6387134be92cd624fd04413f912e622e05702b466b24998cb0fe95a4b0cd3') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-5ee5ff78-7764-473f-9a19-1f77507daff5', 'math', 'Equivalent Expressions', null, 'If 3(2x - 1) + 4(x + 2) = ax + b for all values of x, what is the value of a?', '[]'::jsonb, 0, 'Distribute: 6x - 3 + 4x + 8 = 10x + 5. The coefficient of x is 10, so a = 10.', 'ai', true, 'medium', 'model', 'spr', '10', null, null, 'active', '8107288643fb62555bf3e2eba62f5560f962d82ae381e72c61c141deba4061f2') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-e0b0860f-6a0d-4428-8941-99f33d4db517', 'math', 'Equivalent Expressions', null, 'If (x + 2)(x - 3) = x^2 + kx - 6 for all values of x, what is the value of k?', '[]'::jsonb, 0, 'Expand the left side: x^2 - 3x + 2x - 6 = x^2 - x - 6. Comparing coefficients of x gives k = -1.', 'ai', true, 'medium', 'model', 'spr', '-1', null, null, 'active', '3f0dc73e6b040f5c616f458f1ae76aa49c9966ba4f5ca9d28f8161f5eae5adf7') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-3585f272-9566-4a2b-a9d7-629c469fba32', 'math', 'Equivalent Expressions', null, 'Which expression is equivalent to \((3x^2y^3)^2(2x^3y)^3\)?', '["72x^{13}y^9","72x^{12}y^9","72x^{13}y^8","72x^{12}y^8"]'::jsonb, 0, 'Apply the power rule: (3x^2y^3)^2 = 9x^4y^6 and (2x^3y)^3 = 8x^9y^3. Multiply coefficients: 9 * 8 = 72. Add exponents for x: 4 + 9 = 13. Add exponents for y: 6 + 3 = 9. The equivalent expression is 72x^{13}y^9.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'b3921bdc6f363bd5e8e3eab01757bb04085a56aba4f74824bea7cc41cdfa4452') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-08934c7f-44ee-4b27-a5fb-c3e17678a893', 'math', 'Equivalent Expressions', null, 'If 4^(x+1) = 8^(x-2), what is the value of x?', '[]'::jsonb, 0, 'Rewrite both sides with base 2: 4^(x+1) = (2^2)^(x+1) = 2^(2x+2); 8^(x-2) = (2^3)^(x-2) = 2^(3x-6). Equate exponents: 2x+2 = 3x-6. Solve: 2+6 = 3x-2x → x = 8.', 'ai', true, 'medium', 'model', 'spr', '8', null, null, 'active', '8211575662cd3be8e1556d008be28220a1b934849ba68f91fd4df397078964c5') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-21d5cee0-ddcb-46d1-ac7a-87c23df68cd1', 'math', 'Equivalent Expressions', null, 'Which of the following is equivalent to \(\frac{3x^2 - 12}{x^2 - x - 6} \cdot \frac{x^2 - 4x + 4}{x^2 - 4}\) for all \(x\) such that \(x \neq -2, 2, 3\)?', '["\\(\\frac{3(x-2)^2}{(x-3)(x+2)}\\)","\\(\\frac{3(x-2)}{x-3}\\)","\\(\\frac{3(x+2)}{x-3}\\)","\\(\\frac{3(x-2)^2}{x+2}\\)"]'::jsonb, 0, 'Factor each polynomial: 3x^2 - 12 = 3(x-2)(x+2); x^2 - x - 6 = (x-3)(x+2); x^2 - 4x + 4 = (x-2)^2; x^2 - 4 = (x-2)(x+2). The product becomes [3(x-2)(x+2) / ((x-3)(x+2))] * [(x-2)^2 / ((x-2)(x+2))] = 3(x-2)^2 / [(x-3)(x+2)] after canceling common factors. Thus the correct choice is \(\frac{3(x-2)^2}{(x-3)(x+2)}\).', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'a6a2e744d106fee4b194d087617a3d60baa2082796287707b9498b52eff7e551') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-c6648e20-c483-42ac-a693-8d058e3f517b', 'math', 'Equivalent Expressions', null, 'If \(x \neq 0\), \(y \neq 0\), and \(x \neq y\), which of the following is equivalent to \(\frac{\frac{1}{x} + \frac{1}{y}}{\frac{1}{x} - \frac{1}{y}}\)?', '["\\(\\frac{x+y}{y-x}\\)","\\(\\frac{x+y}{x-y}\\)","\\(\\frac{x-y}{x+y}\\)","\\(\\frac{y-x}{x+y}\\)"]'::jsonb, 0, 'Combine the fractions in the numerator and denominator: numerator = (y+x)/(xy), denominator = (y-x)/(xy). Dividing the two gives (x+y)/(y-x). The correct choice is \(\frac{x+y}{y-x}\).', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '4d43ae924bce735b9209c97582b9903bf1cee17f1bd9d2dbce67799d225789a6') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-87c45a61-7c36-422a-86f3-2d8d6cac60c3', 'math', 'Equivalent Expressions', null, 'For x > 3, which of the following is equivalent to \(\frac{x^2 - 5x + 6}{x^2 - 9}\)?', '["\\(\\frac{x-2}{x-3}\\)","\\(\\frac{x-2}{x+3}\\)","\\(\\frac{x+2}{x-3}\\)","\\(\\frac{x+2}{x+3}\\)"]'::jsonb, 1, 'Factor numerator as (x-2)(x-3) and denominator as (x-3)(x+3). Since x > 3, the factor (x-3) is nonzero and can be canceled, leaving (x-2)/(x+3).', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'ecb127f74924a432fc3eec49b47cbc8e93f54d2b5ff88bd382ef2e39c9625c0f') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-3772d631-1a16-4e18-94e7-e28f4fd0b8fb', 'math', 'Equivalent Expressions', null, 'If \(\frac{2^{x+3} \cdot 4^{x-1}}{8^x} = 2^k\) for all real numbers \(x\), what is the value of \(k\)?', '[]'::jsonb, 0, 'Rewrite all bases as powers of 2: 4^(x-1) = (2^2)^(x-1) = 2^(2x-2); 8^x = (2^3)^x = 2^(3x). The numerator becomes 2^(x+3) * 2^(2x-2) = 2^(x+3+2x-2) = 2^(3x+1). Divide by 2^(3x): 2^(3x+1) / 2^(3x) = 2^(3x+1-3x) = 2^1 = 2. So the expression simplifies to 2, which is 2^1. Therefore k = 1.', 'ai', true, 'hard', 'model', 'spr', '1', null, null, 'active', '8a06eae3d145d656a32a814671d8dfd3f1cf896c57ffba8682fc05026bb48ed7') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-d067135c-f1f0-4814-986b-fcf7dacba66b', 'math', 'Equivalent Expressions', null, 'If (2x+1)/(x^2-1) = A/(x-1) + B/(x+1) for all x except ±1, what is the value of A+B?', '[]'::jsonb, 0, 'Multiply both sides by (x-1)(x+1) to clear denominators: 2x+1 = A(x+1) + B(x-1). Expand the right side: A(x+1) + B(x-1) = Ax + A + Bx - B = (A+B)x + (A-B). Equate coefficients with the left side: coefficient of x gives A+B = 2, constant term gives A-B = 1. Solving the system: add the equations to get 2A = 3, so A = 3/2; then B = 2 - A = 1/2. Thus A+B = 2.', 'ai', true, 'hard', 'model', 'spr', '2', null, null, 'active', '980332e06d3b8d375f070299746aa290e5c18e8079629a621618e732743e0384') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-2d032491-af87-4b1d-9b4a-d11a2ec30cb8', 'math', 'Equivalent Expressions', null, 'If (∛(x^2) * √x)^n = x^5 for all x > 0, what is the value of n?', '[]'::jsonb, 0, 'Rewrite the radicals as exponents: ∛(x^2) = x^(2/3) and √x = x^(1/2). Their product is x^(2/3 + 1/2) = x^(4/6 + 3/6) = x^(7/6). Raising to the nth power gives (x^(7/6))^n = x^(7n/6). Set this equal to x^5: 7n/6 = 5. Multiply both sides by 6: 7n = 30. Divide by 7: n = 30/7.', 'ai', true, 'hard', 'model', 'spr', '30/7', null, null, 'active', 'e3cf254d908d056938a18ba18a92a361c00fb6258fed1be8b0b8a8d1230792a9') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-3f429411-6687-4d5b-b6b0-dd03f6a174d3', 'math', 'Exponential Growth', null, 'The value of a rare stamp increases by 5% each year. If the stamp is worth $200 today, what will be its value, in dollars, exactly one year from now?', '[]'::jsonb, 0, 'A 5% increase means the value is multiplied by 1.05. 200 * 1.05 = 210.', 'ai', true, 'easy', 'model', 'spr', '210', null, null, 'active', 'cabdd6501228bb0c9a7d4ff2ce04c7793ed8a2838fb8e87ed027253c40f161e0') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-2b483283-6226-49a4-b911-36a6eaea70d2', 'math', 'Exponential Growth', null, 'A population of bacteria doubles every hour. If the initial population is 150, what is the population after 3 hours?', '[]'::jsonb, 0, 'After 3 hours, the population doubles 3 times. Multiply the initial population by 2^3: 150 * 8 = 1200.', 'ai', true, 'easy', 'model', 'spr', '1200', null, null, 'active', 'fe7daa202d063b2b573051e1f5c1b3c12da6eb6b82e08d2d9f3463c2f7081ce3') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-c317017b-4a9d-43c9-9b9d-7e10732ef120', 'math', 'Exponential Growth', null, 'A savings account earns 5% interest compounded annually. If the initial deposit is $1,000, what is the balance after 2 years?', '["$1,100.00","$1,102.50","$1,050.00","$1,000.25"]'::jsonb, 1, 'The balance after 2 years is 1000(1.05)^2 = 1000 * 1.1025 = $1,102.50. The other choices result from simple interest (1000 + 1000*0.05*2 = 1100), one year of growth (1050), or a miscalculation.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'b596987b62e934ce75c7ac274724afc45b6a94ad0dd01d5676d559ed08a75af2') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-9efe3a60-e3c3-4745-a8d9-c77a28eba8d8', 'math', 'Exponential Growth', null, 'A savings account earns 5% interest compounded annually. If the initial deposit is $1000, which function gives the balance after t years?', '["1000(1.05)^t","1000(0.05)^t","1000 + 0.05t","1000(1.5)^t"]'::jsonb, 0, 'For annual compound interest, the balance is the initial deposit multiplied by (1 + interest rate) raised to the number of years. With a 5% rate, the growth factor is 1.05, so the function is 1000(1.05)^t.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '38cee1099240ebca20d02caac0e8b9855ebf385163f593c149115b50daeb27bd') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-d37c712a-eec2-4ee1-a326-8876a86975f5', 'math', 'Exponential Growth', null, 'The value of a car decreases by 15% each year. If the car is worth $20,000 today, which expression represents its value after t years?', '["20000(0.15)^t","20000(0.85)^t","20000(1.15)^t","20000(1 - 0.15t)"]'::jsonb, 1, 'A 15% decrease means the car retains 85% of its value each year, so the decay factor is 0.85. The value after t years is 20000(0.85)^t.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'a96218f5a97b2ad1bde3d5a1fd199f9e873c4bfe9704146575bb6fb31306cdad') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-3c264960-fcaa-4f81-9ec5-ac88067286ae', 'math', 'Exponential Growth', null, 'A population of bacteria doubles every hour. If the initial population is 500, what is the population after 3 hours?', '["1,500","3,000","4,000","8,000"]'::jsonb, 2, 'The population after t hours is given by 500 * 2^t. For t = 3, the population is 500 * 2^3 = 500 * 8 = 4,000.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '2a2b6e371eaa965c3ec6f83da46da6da740274d37185ea6e774c0cf011116003') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-5e971ec8-de1a-41a0-ad5e-0a16b5ab75fd', 'math', 'Exponential Growth', null, 'A savings account earns 6% interest compounded annually. If no additional deposits or withdrawals are made, what is the balance after 2 years on an initial deposit of $2000?', '["2247.20","2120.00","2382.03","2240.00"]'::jsonb, 0, 'The balance after 2 years is 2000(1.06)^2 = 2000(1.1236) = 2247.20. The other choices correspond to common errors: 2120.00 is the balance after 1 year, 2382.03 is after 3 years, and 2240.00 is the result of simple interest (2000 * 1.12).', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '8025a52f33e46d04fa70e05ae2721b84cff393d25efa82090cb95c09825608b8') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-f5bca328-fb06-49db-8616-9774345eec6b', 'math', 'Exponential Growth', null, 'A population of bacteria doubles every 5 hours. If the initial population is 300, what is the population after 15 hours?', '["2400","1800","1200","4800"]'::jsonb, 0, 'The number of doubling periods is 15 / 5 = 3. The population after 3 doublings is 300 * 2^3 = 300 * 8 = 2400.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'e9230f1e919074d6fafa875aec8d10a7e65a8d864811dc668f3a8e1df91184b2') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-efff9e56-07f5-4166-b5e3-0b7d77a4bf8b', 'math', 'Exponential Growth', null, 'A car''s value depreciates by 8% each year. If the car is initially worth $20,000, which function models its value V(t) after t years?', '["V(t) = 20000(0.92)^t","V(t) = 20000(0.08)^t","V(t) = 20000(1.08)^t","V(t) = 20000(1.92)^t"]'::jsonb, 0, 'Depreciation of 8% per year means the car retains 100% - 8% = 92% of its value each year, so the decay factor is 0.92. The exponential model is V(t) = 20000(0.92)^t.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '91abcc1735e1c4caa84418c074bda6581641e62f1a2daec0b87924e2a9880ad8') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-f5cc83d9-17a1-420f-9d77-a4bf7f636577', 'math', 'Exponential Growth', null, 'A population of bacteria doubles every 3 hours. If the initial population is 500, which expression gives the population after 15 hours?', '["500(2)^5","500(2)^15","500(2)^(15/2)","500(2)^(3/15)"]'::jsonb, 0, 'The number of doubling periods in 15 hours is 15 ÷ 3 = 5. The population after t hours is initial × 2^(t/3), so after 15 hours it is 500 × 2^(15/3) = 500(2)^5.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '2db8973445d3d9e6e68cbc744d7668c0d02a4f1c63865fab88321573f779264b') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-fd8a1c8b-c60f-47a7-a957-902d28767e4a', 'math', 'Exponential Growth', null, 'The number of bacteria in a petri dish is modeled by the function N(t) = 200(2)^(t/5), where t is the time in hours. After how many hours will the number of bacteria reach 6,400?', '[]'::jsonb, 0, 'Set N(t) = 6400: 200 * 2^(t/5) = 6400. Divide both sides by 200: 2^(t/5) = 32. Since 32 = 2^5, we have 2^(t/5) = 2^5, so t/5 = 5, and t = 25.', 'ai', true, 'medium', 'model', 'spr', '25', null, null, 'active', '6ea6e858de4b2d4d5831a4e4e93a24d1be321e280f10535378393ded7ee9d82e') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-9c75a639-f55e-43f2-93a5-2065da524316', 'math', 'Exponential Growth', null, 'A population of bacteria increases by 50% every hour. If there are 810 bacteria after 4 hours, how many bacteria were there initially?', '[]'::jsonb, 0, 'The growth factor per hour is 1 + 0.50 = 1.5. After 4 hours, the population is initial * (1.5)^4. Compute (1.5)^4 = (3/2)^4 = 81/16. So 810 = initial * 81/16. Multiply both sides by 16/81: initial = 810 * 16/81 = 10 * 16 = 160.', 'ai', true, 'medium', 'model', 'spr', '160', null, null, 'active', '5dd9772c95e4a4b51d1d04845316cee8bd84c876eb4fbb92e07d63fb419cafd8') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-b8808e7e-564e-4e47-bf5e-20ff3e50cf8e', 'math', 'Exponential Growth', null, 'An investment account earns interest compounded annually. The balance B, in dollars, after t years is given by B(t) = 1000(1.045)^t. After how many years will the balance first exceed $2000?', '["14","15","16","17"]'::jsonb, 2, 'Set 1000(1.045)^t > 2000, which simplifies to (1.045)^t > 2. Taking natural logs: t * ln(1.045) > ln(2). Since ln(2) ≈ 0.6931 and ln(1.045) ≈ 0.0440, t > 0.6931/0.0440 ≈ 15.75. The smallest integer t satisfying this is 16, so the balance first exceeds $2000 after 16 years.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'bc7b78d076c724643f8b1376d1a8de558c6749110a39cec7e5d30cacbf51c40b') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-0748e0fd-3af2-4af0-8667-99c60ae675d7', 'math', 'Exponential Growth', null, 'A population of rabbits grows exponentially according to the equation P(t) = 1000e^(kt), where P(t) is the population after t months. After 6 months, the population is 2000. After how many months will the population be 8000?', '[]'::jsonb, 0, 'First, find the growth constant k using P(6)=2000: 1000e^(6k)=2000 → e^(6k)=2 → 6k=ln2 → k=ln2/6. Then set P(t)=8000: 1000e^(kt)=8000 → e^(kt)=8 → kt=ln8=3ln2. Substitute k: (ln2/6)·t = 3ln2 → t/6 = 3 → t=18.', 'ai', true, 'hard', 'model', 'spr', '18', null, null, 'active', 'd42f834551c102fca04bcd7ec3cfba91075cec8a94b9844e2dd9f8b3558637dc') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-61574a80-fbde-4a41-b250-cb681c7894ae', 'math', 'Exponential Growth', null, 'City A has a population of 100,000 and grows at a rate of 5% per year. City B has a population of 80,000 and grows at a rate of 8% per year. After how many complete years will the population of City B first exceed that of City A?', '["6","7","8","9"]'::jsonb, 2, 'Model populations: A(t) = 100,000(1.05)^t, B(t) = 80,000(1.08)^t. Set B(t) > A(t): 80,000(1.08)^t > 100,000(1.05)^t. Divide both sides by 80,000(1.05)^t: (1.08/1.05)^t > 1.25. Simplify base: 1.08/1.05 ≈ 1.02857. Take natural log: t * ln(1.02857) > ln(1.25). Compute: ln(1.25) ≈ 0.22314, ln(1.02857) ≈ 0.02817. t > 0.22314 / 0.02817 ≈ 7.92. The smallest integer t satisfying this is 8. After 8 complete years, City B''s population first exceeds City A''s.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'a5909fe33ff05036611a449859d8f0a6b823ef2e678ee24c9aefe57322da3eca') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-b94bafca-437d-48da-99c5-3b24ef5bb4f1', 'math', 'Exponential Growth', null, 'A population of bacteria grows according to the model P(t)=P0 * a^(t/2), where P0 is the initial population, t is the time in hours, and a is a positive constant. If the population triples in 6 hours, what is the value of a?', '["∛3","3","9","√3"]'::jsonb, 0, 'Substituting t=6 gives P(6)=P0 * a^(6/2)=P0 * a^3. Since the population triples, P(6)=3P0, so a^3=3, thus a=∛3. The correct choice is ∛3.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '002aaddb993680c179eaaf3150d31c842e21cf3a6b3e0e6ea91013ceeb2f2603') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-93a427c9-e752-490f-bece-b63a3449b9cf', 'math', 'Exponential Growth', null, 'A population of bacteria grows exponentially according to the model P(t)=P0 * 2^(t/d), where P0 is the initial population, t is the time in hours, and d is the doubling time in hours. At t=0, the population is 500. At t=10, the population is 4000. What is the doubling time, in hours?', '["10/3","3","10","20/3"]'::jsonb, 0, 'Since P(10)=500 * 2^(10/d)=4000, we have 2^(10/d)=8=2^3, so 10/d=3, giving d=10/3. The correct choice is 10/3.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'ed5dff8a6f8d65278c59f79f4de8a205a5fc259456f7860cae69b805913a43cb') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-7f6e6df2-c191-4733-a1a8-a6e9657cdffb', 'math', 'Exponential Growth', null, 'A population of insects grows exponentially. At t = 2 days, the population is 400. At t = 5 days, the population is 800. Which of the following functions gives the population P(t) after t days?', '["P(t) = 400(2)^((t-2)/3)","P(t) = 400(2)^(t/3)","P(t) = 200(2)^(t/3)","P(t) = 400(2)^((t-5)/3)"]'::jsonb, 0, 'Assume the model P(t) = P0 * b^t. Using the given points: P(2) = P0 * b^2 = 400 and P(5) = P0 * b^5 = 800. Dividing the second equation by the first gives b^3 = 2, so b = 2^(1/3). Substitute back to find P0: P0 * 2^(2/3) = 400, so P0 = 400 / 2^(2/3). Then P(t) = (400 / 2^(2/3)) * 2^(t/3) = 400 * 2^((t-2)/3). The correct choice is P(t) = 400(2)^((t-2)/3).', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'b2322a56f82e29a0316cc5ccd8d27d579135c67188de442c9e9cc9502ecbf960') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-926995aa-031d-4559-8874-e52bd9e51801', 'math', 'Exponents', null, 'Evaluate: 3^2 * 3^3', '["3^5","3^6","9^5","27^2"]'::jsonb, 0, 'When multiplying powers with the same base, add the exponents: 3^2 * 3^3 = 3^(2+3) = 3^5.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'c060934138f4c44eab9df5590023f2829873c17a692f2a249fc6b1dcb77f9f3c') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-cc611450-083d-479a-be46-d9ced11cc872', 'math', 'Exponents', null, 'Simplify: \(\frac{x^3 \cdot x^5}{x^4}\)', '["x^2","x^4","x^7","x^12"]'::jsonb, 1, 'When multiplying like bases, add the exponents: x^3 * x^5 = x^(3+5) = x^8. When dividing, subtract the exponents: x^8 / x^4 = x^(8-4) = x^4.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '6118d9450171d99d3f273392002a5af6dcc6607daae6881b554a8d94a4b67776') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-16ddf674-cf08-4ee9-88fd-1a2cdcae9910', 'math', 'Exponents', null, 'If 2^(x+2) = 32, what is the value of x?', '[]'::jsonb, 0, 'Rewrite 32 as a power of 2: 32 = 2^5. Then 2^(x+2) = 2^5, so the exponents are equal: x + 2 = 5. Subtract 2 to get x = 3.', 'ai', true, 'easy', 'model', 'spr', '3', null, null, 'active', '620d431647d3664ced5811d3b0d891b8c941eb7516a222fc29b043d59533493a') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-f2cdc55d-d104-4ad4-adf6-87a3110ee5db', 'math', 'Exponents', null, 'What is the value of 9^(1/2) + 16^(1/2)?', '[]'::jsonb, 0, '9^(1/2) is the square root of 9, which is 3. 16^(1/2) is the square root of 16, which is 4. Adding them gives 3 + 4 = 7.', 'ai', true, 'easy', 'model', 'spr', '7', null, null, 'active', '7bab9b3b9f5faf1d73c896c4de8ff192fbdce467f86db8367a594249b1dbc673') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-a3ca6b5c-38dd-4d08-846d-eb93723da675', 'math', 'Exponents', null, 'If (x^5)/(x^2) = x^a, what is the value of a?', '["3","7","10","2.5"]'::jsonb, 0, 'When dividing powers with the same base, subtract the exponents: x^5 / x^2 = x^(5-2) = x^3, so a = 3.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'd6eeb97a979f46cd0a5539cc609ec125edb546ef4da5af4e51cf7da2f40fdd9b') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-3586d6e5-969f-4601-8790-c6412a89000d', 'math', 'Exponents', null, 'What is the value of 2^(-3)?', '["1/8","-8","-1/8","8"]'::jsonb, 0, 'A negative exponent means taking the reciprocal of the base raised to the positive exponent: 2^(-3) = 1/(2^3) = 1/8. The correct choice is 1/8.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'ab0591930bee31baf24a3fb72adf321c103254ce21564b547eac7a106a081436') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-7c784bd8-a0b8-4b43-8eda-75e7243063a2', 'math', 'Exponents', null, 'If x > 0, which of the following is equivalent to (27x^9)^(2/3)?', '["9x^6","18x^6","9x^5","27x^6"]'::jsonb, 0, 'Apply the exponent 2/3 to both factors: 27^(2/3) = (3^3)^(2/3) = 3^2 = 9, and (x^9)^(2/3) = x^(9 * 2/3) = x^6. The expression simplifies to 9x^6.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'b49dfab26f37bb870e6c06544cea31e704fcb7622b49b03c42b1ba38818cd8c0') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-833944ec-f045-46b3-91f9-52d3db23517f', 'math', 'Exponents', null, 'If 2^(x+1) = 8^(x-2), what is the value of x?', '["7/2","3","4","5"]'::jsonb, 0, 'Rewrite 8 as 2^3: 2^(x+1) = (2^3)^(x-2) = 2^(3x-6). Equate the exponents: x+1 = 3x-6. Solve for x: 2x = 7, so x = 7/2.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'fb1f1e606b47c2837e5dbed8924ad1169295b62a87872cbe7c0fd873b3558398') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-dfb46f88-7a0f-49d6-914f-d92f14587266', 'math', 'Exponents', null, 'Which of the following is equivalent to (x^-2 y^3) / (x^3 y^-1)?', '["y^4 / x^5","x^5 / y^4","x y^2","y^2 / x"]'::jsonb, 0, 'Apply the quotient rule for exponents: subtract the exponents of like bases. For x: -2 - 3 = -5. For y: 3 - (-1) = 4. The expression simplifies to x^-5 y^4, which equals y^4 / x^5.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '64566713641e0dd3cca340ee95aef341edad5bde0a862cdca0db968dc4187dde') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-8bddfd58-e696-4d06-b5d4-a6ebbf98a461', 'math', 'Exponents', null, 'Which expression is equivalent to (16x^8)^{3/4}?', '["8x^6","12x^6","8x^{11}","12x^{11}"]'::jsonb, 0, 'Apply the exponent to both factors: 16^{3/4} * (x^8)^{3/4}. 16^{3/4} = (16^{1/4})^3 = 2^3 = 8. (x^8)^{3/4} = x^{8 * 3/4} = x^6. The product is 8x^6.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '5313327d1576f486f5f8dbba45d92681cc0a96560e865fbb118ff9c9f2fd5a23') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-6d99e1ef-4c52-4cc5-bba2-59a0fa98c9a7', 'math', 'Exponents', null, 'Which of the following is equivalent to (x^{2/3} * x^{1/2})^6, for x > 0?', '["x^5","x^6","x^7","x^8"]'::jsonb, 2, 'Combine the exponents inside the parentheses: x^{2/3 + 1/2} = x^{4/6 + 3/6} = x^{7/6}. Then apply the outer exponent: (x^{7/6})^6 = x^{(7/6)*6} = x^7. The correct choice is x^7.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'ef2066da9f2f541d2a1f781e9a00255f1376acf6a904e4763a85ae363d23b73e') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-ff1e5dfd-fa5c-4949-88da-4ec4b0b02b2b', 'math', 'Exponents', null, 'If x > 0, which of the following is equivalent to (x^(2/3) * x^(1/2)) / x^(1/6)?', '["x","x^(5/6)","x^(7/6)","x^(1/3)"]'::jsonb, 0, 'Combine the exponents in the numerator: x^(2/3 + 1/2) = x^(4/6 + 3/6) = x^(7/6). Then divide by x^(1/6): x^(7/6 - 1/6) = x^(6/6) = x^1 = x. So the expression simplifies to x.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '5510333b72d4833be7fe85a265eee21392c7ccf8a0c4f4fca6d4e3eae837c094') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-924ea2cd-f386-4353-ba3b-1e7878d7cbab', 'math', 'Exponents', null, 'If \(\frac{5^{x+1} \cdot 25^{x-2}}{125^{x-3}} = 5^{2x-1}\), what is the value of \(x\)?', '[]'::jsonb, 0, 'Rewrite 25 as 5^2 and 125 as 5^3. The left side becomes 5^{x+1} * (5^2)^{x-2} / (5^3)^{x-3} = 5^{x+1} * 5^{2x-4} / 5^{3x-9} = 5^{(x+1)+(2x-4)-(3x-9)} = 5^{6}. So 5^6 = 5^{2x-1}. Equate exponents: 6 = 2x - 1, so 2x = 7, x = 7/2.', 'ai', true, 'hard', 'model', 'spr', '7/2', null, null, 'active', '0a499bb56c063a33192190a4b6ce3d4eb3141b08aab98548b23917decfc5ccea') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-f2df7d06-a8d2-408c-b785-aeda640ca1cd', 'math', 'Exponents', null, 'If \(\frac{2^x \cdot 4^{x-1}}{8^{x-2}} = 16^{1/2} \cdot 2^x\), what is the value of \(x\)?', '[]'::jsonb, 0, 'Rewrite 4 as 2^2, 8 as 2^3, and 16^{1/2} as 4. Left side: 2^x * (2^2)^{x-1} / (2^3)^{x-2} = 2^x * 2^{2x-2} / 2^{3x-6} = 2^{x+2x-2-3x+6} = 2^4 = 16. Right side: 4 * 2^x. So 16 = 4 * 2^x. Divide by 4: 4 = 2^x, so 2^2 = 2^x, thus x = 2.', 'ai', true, 'hard', 'model', 'spr', '2', null, null, 'active', '0541caffe94c2fd80b999f9f04205cd896d9d9ea020aaa7b30dee27e05ee6c2c') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-8ca1edb4-e5b8-40f3-a320-983496794328', 'math', 'Exponents', null, 'If 2^(2x) - 5*2^x + 4 = 0, what is the sum of all possible values of x?', '[]'::jsonb, 0, 'Let y = 2^x. Then 2^(2x) = (2^x)^2 = y^2. The equation becomes y^2 - 5y + 4 = 0. Factor: (y - 1)(y - 4) = 0, so y = 1 or y = 4. If 2^x = 1, then x = 0. If 2^x = 4, then x = 2. The sum of all possible values of x is 0 + 2 = 2.', 'ai', true, 'hard', 'model', 'spr', '2', null, null, 'active', '5486c7bd125671658164489ed548ecc3e5d85e878c51415ac85474a9780489cf') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-ac28f02c-19bf-4697-ae4d-7164f8370c52', 'math', 'Exponents', null, 'If (x^(1/2) * x^(1/3))^6 = 2^10, what is the value of x?', '[]'::jsonb, 0, 'Combine exponents inside the parentheses: x^(1/2) * x^(1/3) = x^(1/2 + 1/3) = x^(5/6). Raise to the 6th power: (x^(5/6))^6 = x^((5/6)*6) = x^5. The equation becomes x^5 = 2^10. Since 2^10 = (2^2)^5 = 4^5, we have x^5 = 4^5, so x = 4.', 'ai', true, 'hard', 'model', 'spr', '4', null, null, 'active', 'd86e6c0b0ff5d90fc1b92a565e73aaff8b09dbb89fbc1f3ce51479e46bedd095') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-fde8b891-4c65-4fdd-b2fe-63c7815c038e', 'math', 'Exponents', null, 'If x^(1/2) + x^(-1/2) = 3, what is the value of x + x^(-1)?', '["3","7","9","1"]'::jsonb, 1, 'Square both sides of the given equation: (x^(1/2) + x^(-1/2))^2 = 3^2. Expand the left side: x + 2 * x^(1/2) * x^(-1/2) + x^(-1) = x + 2 + x^(-1). Set equal to 9: x + 2 + x^(-1) = 9. Subtract 2 from both sides: x + x^(-1) = 7.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '0672752c5dbcfdb04638d1c52301a32a04045c28926aa5b8ee0c02ee23bf7e86') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-723b5f3d-b0e0-4185-a58e-7fbe0ef8df41', 'math', 'Exponents', null, 'If 3^(x+2) + 3^(x+1) = 108, what is the value of x?', '["1","2","3","4"]'::jsonb, 1, 'Factor out 3^(x+1) from the left side: 3^(x+1)(3 + 1) = 3^(x+1) * 4 = 108. Divide both sides by 4: 3^(x+1) = 27. Since 27 = 3^3, we have 3^(x+1) = 3^3, so x+1 = 3, giving x = 2.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'c004ef8abca647130a2b20020a99a839199816261c99dc1b8a2e06f57e999a3f') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-ea92b344-a1d7-4f9a-8f74-51225e1fb60e', 'math', 'Functions', null, 'If f(x) = 3x - 5, what is the value of f(2)?', '["1","2","3","4"]'::jsonb, 0, 'Substitute 2 for x: 3(2) - 5 = 6 - 5 = 1.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '0dc6ed1208e542271f04819790e5f865129728160ae82e8c285767ce0e5345b0') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-0cc41b25-2781-4d2f-b4b0-ecfd2cb032cc', 'math', 'Functions', null, 'The function g is defined by g(x) = x^2 - 3. What is the value of g(-2)?', '["-7","-1","1","7"]'::jsonb, 2, 'Substitute -2 for x: (-2)^2 - 3 = 4 - 3 = 1.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '29e8514ecbcb2a9c0bd75e633cf780f6433ec425a3304294d8f092c21ce15678') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-ea5026c9-d74a-4da3-bcff-dba0fbdc6d68', 'math', 'Functions', null, 'The function g is defined by g(x) = 2x + 5. For what value of x does g(x) = 13?', '[]'::jsonb, 0, 'Set g(x) equal to 13: 2x + 5 = 13. Subtract 5 from both sides: 2x = 8. Divide by 2: x = 4.', 'ai', true, 'easy', 'model', 'spr', '4', null, null, 'active', 'f945b7ffb1a2a2945de914131d1c6eeca25bd7698d79d22f0315ff000227925d') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-c04e08cb-a448-4c06-a418-3eccf06fc39c', 'math', 'Functions', null, 'If f(x) = 4x - 3, what is the value of f(2)?', '[]'::jsonb, 0, 'Substitute 2 for x: f(2) = 4(2) - 3 = 8 - 3 = 5.', 'ai', true, 'easy', 'model', 'spr', '5', null, null, 'active', '086ecf4968249f5d53e38c1469bbc6e7c21f5ce13abbd4ccb3e1d507c99a0972') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-a395db9d-285d-4ff6-ada9-44e64b32fac5', 'math', 'Functions', null, 'What is the domain of the function f(x) = sqrt(x - 5)?', '["x ≥ 5","x > 5","x ≤ 5","x < 5"]'::jsonb, 0, 'The expression inside the square root must be nonnegative, so x - 5 ≥ 0, which gives x ≥ 5.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'ae3c0bf628058f06f2dc592ea54af37efae76acea97be7825d3ffd02dab9f35c') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-3c103669-5cf1-4b97-b35a-564427caf56a', 'math', 'Functions', null, 'If f(x) = 2x + 3, what is the value of f(4)?', '["11","10","12","8"]'::jsonb, 0, 'Substitute 4 for x: f(4) = 2(4) + 3 = 8 + 3 = 11.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '6d8907e012322b70b326dc81a2e13e156af5fd610c1deb6415c01c16d491b581') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-40a4f5b4-e5b8-4a5b-9b97-bbbc2deae9d6', 'math', 'Functions', null, 'Let f(x) = x^2 - 1 and g(x) = 2x + 1. What is the value of f(g(0))?', '["-1","0","1","3"]'::jsonb, 1, 'First evaluate the inner function: g(0) = 2(0) + 1 = 1. Then evaluate f at that result: f(1) = (1)^2 - 1 = 0. The correct choice is 0.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'a2878a5497a739ea3f7629a36dac34b08b7eb39f16e90e58a2a308735fe144f9') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-30981db0-6877-4a58-8afd-780d327ef8db', 'math', 'Functions', null, 'If f(x) = 2x + 3, what is the value of f(a + 1) - f(a)?', '["2","4","2a + 2","2a + 5"]'::jsonb, 0, 'Compute f(a+1) = 2(a+1) + 3 = 2a + 5. Compute f(a) = 2a + 3. Subtract: (2a + 5) - (2a + 3) = 2. The correct choice is 2.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '04e5467f513601a448a17cb84b05e3e26a78313b287042b24d55ca12553b42ed') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-066cc382-ce6f-4679-8f69-b060337bd901', 'math', 'Functions', null, 'The function h is defined by h(x) = 2x + k, where k is a constant. If h(3) = 10, what is the value of h(5)?', '[]'::jsonb, 0, 'First, use h(3) = 10 to find k: 2(3) + k = 10 → 6 + k = 10 → k = 4. Then, evaluate h(5): h(5) = 2(5) + 4 = 10 + 4 = 14.', 'ai', true, 'medium', 'model', 'spr', '14', null, null, 'active', '46baae9a4e7859c8c44047e592cc80fea1f5818322c67607789263837b18df93') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-20b7d194-82f5-48c6-b00e-a96da388deea', 'math', 'Functions', null, 'If f(x) = 3x - 7 and g(x) = x^2 + 1, what is the value of f(g(2))?', '[]'::jsonb, 0, 'First, evaluate g(2): g(2) = (2)^2 + 1 = 4 + 1 = 5. Then, evaluate f(5): f(5) = 3(5) - 7 = 15 - 7 = 8.', 'ai', true, 'medium', 'model', 'spr', '8', null, null, 'active', 'a73de078e2dcc00c7a05c1cdbcccde25e1928760f196e33c549c1ad69d01ffb4') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-c19e8e7e-8f1b-4f80-9faf-caa3f0517746', 'math', 'Functions', null, 'Let g(x) = 3x - 4 and h(x) = x^2 + 1. What is the value of g(h(2))?', '[]'::jsonb, 0, 'First, find h(2): 2^2 + 1 = 4 + 1 = 5. Then, find g(5): 3(5) - 4 = 15 - 4 = 11.', 'ai', true, 'medium', 'model', 'spr', '11', null, null, 'active', 'fa8a76265d7b68c92849383b44ba1bf040f381327fe22fc8a360702031d2acf0') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-024c3c0d-7197-4450-8642-53264c7edfe1', 'math', 'Functions', null, 'If f(x) = 2x^2 - 3x + 1, what is the value of f(2) - f(1)?', '[]'::jsonb, 0, 'First, evaluate f(2): 2(2)^2 - 3(2) + 1 = 8 - 6 + 1 = 3. Then evaluate f(1): 2(1)^2 - 3(1) + 1 = 2 - 3 + 1 = 0. Subtract: 3 - 0 = 3.', 'ai', true, 'medium', 'model', 'spr', '3', null, null, 'active', '1754511c267d364a53a847c4e6d04195d87c3b40bd61605fef75a0a8bf662cb7') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-8929616b-00d8-44b5-bd7a-35da1a3325dd', 'math', 'Functions', null, 'The function f is defined by f(x) = ax^2 + b, where a and b are constants. If f(2) = 5 and f(3) = 14, what is the value of f(4)?', '[]'::jsonb, 0, 'Substitute the given values: f(2) = a(2)^2 + b = 4a + b = 5, and f(3) = a(3)^2 + b = 9a + b = 14. Subtract the first equation from the second: (9a + b) - (4a + b) = 14 - 5, so 5a = 9, giving a = 9/5. Substitute back: 4(9/5) + b = 5, so 36/5 + b = 5, b = 5 - 36/5 = -11/5. Then f(4) = a(4)^2 + b = 16(9/5) + (-11/5) = (144 - 11)/5 = 133/5.', 'ai', true, 'hard', 'model', 'spr', '133/5', null, null, 'active', '995186b878da20dc01e63c15d964e77da5e19216965c39d0717bcdf42180f7c5') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-7c49ba83-379c-4be1-a3ee-52da0b51c4e8', 'math', 'Functions', null, 'The function f is defined as f(x) = { 2x + a for x ≤ 1, bx - 3 for x > 1 }, where a and b are constants. If f is continuous at x = 1 and f(2) = 5, what is the value of a + b?', '[]'::jsonb, 0, 'First, use f(2) = 5. Since 2 > 1, f(2) = b(2) - 3 = 2b - 3 = 5, so 2b = 8, b = 4. For continuity at x = 1, the left-hand limit must equal the right-hand limit. Left: f(1) = 2(1) + a = 2 + a. Right: limit as x approaches 1 from above is b(1) - 3 = 4 - 3 = 1. Set equal: 2 + a = 1, so a = -1. Then a + b = -1 + 4 = 3.', 'ai', true, 'hard', 'model', 'spr', '3', null, null, 'active', '9a58ed6d505ff10bd5bcfbff8296b635840a13faa594486be0c474f0d0e09c4e') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-cae86d78-eb58-465e-82f8-ce7ca6849c17', 'math', 'Functions', null, 'Let f(x) = 1/(x - 2) and g(x) = sqrt(x + 1). Which of the following represents the domain of the composite function (f ∘ g)(x)?', '["x >= -1","x >= -1 and x != 3","x > -1 and x != 3","x != 3"]'::jsonb, 1, 'The composite function is (f ∘ g)(x) = f(g(x)) = 1/(sqrt(x + 1) - 2). The expression inside the square root must be nonnegative, so x + 1 >= 0, giving x >= -1. The denominator cannot be zero, so sqrt(x + 1) - 2 != 0, which means sqrt(x + 1) != 2, so x + 1 != 4, giving x != 3. Combining these, the domain is x >= -1 and x != 3.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'db9b46ff98ddf60ddc800753aaa34c11f043feac61fbdc4515fd881a5df0717b') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-38723822-5e79-4b44-b0df-aa0dbdcf7fe8', 'math', 'Functions', null, 'Let f(x) = 2x + 1 and g(x) = x^2 - 2. What is the value of x for which f(g(x)) = g(f(x))?', '["-1","0","1","2"]'::jsonb, 0, 'Compute f(g(x)) = 2(x^2 - 2) + 1 = 2x^2 - 3. Compute g(f(x)) = (2x + 1)^2 - 2 = 4x^2 + 4x - 1. Set them equal: 2x^2 - 3 = 4x^2 + 4x - 1. Simplify to 0 = 2x^2 + 4x + 2, then divide by 2: 0 = x^2 + 2x + 1, which factors as (x + 1)^2 = 0. Thus x = -1.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '078aa8c2d9e53c764b7269a2d737105d31c2cb9770acfa66decd309522f9b96e') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-b2ddf554-bb77-4b5f-81e4-d9dbb7e66bd3', 'math', 'Functions', null, 'The function f is defined as follows: f(x) = 2x + a for x < 3, and f(x) = x^2 - 1 for x ≥ 3, where a is a constant. If f(f(2)) = 15, what is the value of a?', '[]'::jsonb, 0, 'First evaluate f(2). Since 2 < 3, use the first piece: f(2) = 2(2) + a = 4 + a. Now evaluate f(f(2)) = f(4 + a). Determine which piece applies to 4 + a. Case 1: If 4 + a < 3 (i.e., a < -1), then f(4 + a) = 2(4 + a) + a = 8 + 3a. Set equal to 15: 8 + 3a = 15 → 3a = 7 → a = 7/3, which contradicts a < -1. So this case is invalid. Case 2: If 4 + a ≥ 3 (i.e., a ≥ -1), then f(4 + a) = (4 + a)^2 - 1 = a^2 + 8a + 16 - 1 = a^2 + 8a + 15. Set equal to 15: a^2 + 8a + 15 = 15 → a^2 + 8a = 0 → a(a + 8) = 0 → a = 0 or a = -8. Since a ≥ -1, a = 0 is the only valid solution.', 'ai', true, 'hard', 'model', 'spr', '0', null, null, 'active', 'e2a75044ec419d9beed6b84266696dc0f0ede2db6c64f2990ad4498f58130b73') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-bef4d4c8-b704-4284-b45c-8a75f22c3de2', 'math', 'Functions', null, 'The function f is defined by f(x) = x^2 - 4x + 5. The function g is defined by g(x) = f(x+2) - 1. What is the minimum value of g(x)?', '["0","1","2","-1"]'::jsonb, 0, 'Complete the square for f(x): f(x) = (x-2)^2 + 1. Then g(x) = f(x+2) - 1 = ((x+2)-2)^2 + 1 - 1 = x^2. The minimum value of x^2 is 0, so the correct choice is 0.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '2452a6dd4d61a15e637fafe1e6a9a39eb862df600e529d0dc51387d20d365919') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-62638c01-ded5-49c0-857a-f6968636419e', 'math', 'Geometry (Area)', null, 'A rectangle has a length of 12 inches and a width of 5 inches. What is the area of the rectangle in square inches?', '[]'::jsonb, 0, 'Area of a rectangle = length × width = 12 × 5 = 60.', 'ai', true, 'easy', 'model', 'spr', '60', null, null, 'active', '5c81ac5bf8f11458734077e6a6ccf0ba653a23406dc6a4d86b6534f1af85fe3c') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-f5954a25-9555-4122-b665-62b1f8f2c7ef', 'math', 'Geometry (Area)', null, 'A right triangle has legs of length 6 cm and 8 cm. What is the area of the triangle in square centimeters?', '[]'::jsonb, 0, 'Area of a triangle = (1/2) × base × height. Using the legs as base and height: (1/2) × 6 × 8 = 24.', 'ai', true, 'easy', 'model', 'spr', '24', null, null, 'active', 'c6015e3e5dd46d118a020724088e93f3d68ef80471f0fec530bee4815e017c0e') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-49bef98b-5387-4607-bdd8-892dee073403', 'math', 'Geometry (Area)', null, 'A triangle has a base of 10 cm and a height of 6 cm. What is the area of the triangle?', '["30 cm²","60 cm²","16 cm²","32 cm²"]'::jsonb, 0, 'The area of a triangle is (1/2) × base × height: (1/2) × 10 × 6 = 30 cm².', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '2257398fc7abcd921b3aa8bdb1164e794fbf6fa1b5aaa11367c2c7cef75264c4') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-3fa9b399-b378-488e-b02c-2badfce4b461', 'math', 'Geometry (Area)', null, 'A rectangle has a length of 8 inches and a width of 5 inches. What is the area of the rectangle?', '["40 square inches","13 square inches","26 square inches","80 square inches"]'::jsonb, 0, 'The area of a rectangle is length times width: 8 × 5 = 40 square inches.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'd69a6c654b50022a7c1d5b2a8fe35b853900500554fa61ed85ba56c9f1192698') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-66136f04-1c01-41b7-83f9-be30097e6f3c', 'math', 'Geometry (Area)', null, 'A rectangle has a length of 8 inches and a width of 5 inches. What is the area, in square inches?', '["13","26","40","80"]'::jsonb, 2, 'The area of a rectangle is length times width. 8 × 5 = 40, so the area is 40 square inches.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '8b5e1d45370bedeb9da2dbc79a780a438891ff5b467bd3c22784544630ea4de0') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-2029241c-baf1-40df-8045-a4ad6682b8c5', 'math', 'Geometry (Area)', null, 'A triangle has a base of 10 cm and a height of 6 cm. What is the area, in square centimeters?', '["16","30","60","32"]'::jsonb, 1, 'The area of a triangle is one-half times base times height. (1/2) × 10 × 6 = 30, so the area is 30 square centimeters.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '253267fd487fc70b813dda8018dfbe29f25101d54a3fb0037bf1cb70961a1a6e') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-83753583-96b3-459e-8454-4cef6c04d7a3', 'math', 'Geometry (Area)', null, 'A square has a side length of 8. A circle is inscribed in the square so that it touches all four sides. What is the area of the region inside the square but outside the circle?', '["64 - 16π","64 - 8π","16π - 64","64π - 16"]'::jsonb, 0, 'The area of the square is 8^2 = 64. The inscribed circle has a diameter equal to the side length, so its radius is 4, giving an area of π(4^2) = 16π. The area of the shaded region is the difference: 64 - 16π.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'c45e02fd337637cbe3e6c7b0f6f0474ee5a12e70cbb3d7c33c3a47ebec82da7c') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-db6a399d-bbbb-4d0d-8480-a1297858bfff', 'math', 'Geometry (Area)', null, 'A circle has a radius of 6. What is the area of a sector of the circle that has a central angle of 60°?', '["6π","12π","3π","36π"]'::jsonb, 0, 'The area of a sector is (central angle / 360°) × πr^2. With a 60° angle and radius 6, the area is (60/360) × π × 36 = (1/6) × 36π = 6π.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'a9dbfcf3bb6c42636b4cdbe83da2fe61dc19eb32921dee267984244d6f5eedac') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-265282fa-bc64-49f7-892e-74cd5f141b6f', 'math', 'Geometry (Area)', null, 'A circle has a circumference of 12π. What is the area of the circle?', '["12π","24π","36π","144π"]'::jsonb, 2, 'Circumference = 2πr = 12π, so r = 6. Area = πr^2 = π(6)^2 = 36π.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '5a0330e0099545112137b27594455aa1a2f3facf724e6c4b094dc05183f6e51b') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-aec552f6-62e8-4cd2-98fa-794171a43003', 'math', 'Geometry (Area)', null, 'A square has a diagonal of length 10. What is the area of the square?', '["25","50","100","200"]'::jsonb, 1, 'The diagonal of a square is side * √2. So side = 10/√2 = 5√2. Area = (5√2)^2 = 50.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '93dddfaa80ff5ca3087defb9f2f4fc7e399a8faef82bf68a16e291e3c869171a') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-5c67a654-cf59-471e-a99c-42fd01615167', 'math', 'Geometry (Area)', null, 'A rectangle has length 10 and width 6. A semicircle is removed from one of the longer sides, with the diameter of the semicircle coinciding with the entire width. What is the area of the remaining figure?', '["60 - 18π","60 - 9π","60 - 4.5π","60 - 3π"]'::jsonb, 2, 'The area of the rectangle is 10 × 6 = 60. The semicircle has diameter 6, so its radius is 3. The area of a full circle with radius 3 is π(3)² = 9π, so the semicircle area is half of that: 4.5π. The remaining area is 60 - 4.5π.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '52b534cd644f6a571873c4c789607038cff811c117e6b3fb2751c917ec97f255') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-6ed4eb97-5b7f-48c4-b375-f263457e4c32', 'math', 'Geometry (Area)', null, 'In triangle ABC, AB = 8, AC = 5, and the measure of angle A is 30°. What is the area of triangle ABC?', '["10","20","40","10√3"]'::jsonb, 0, 'The area of a triangle given two sides and the included angle is (1/2)(AB)(AC)(sin A). Substituting the values: (1/2)(8)(5)(sin 30°) = (1/2)(40)(1/2) = 10.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '1e4f35c42b91ef1f4464a04e2f1f97208bf2f0fd59f229db08c2140b16da14a2') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-58f123a6-eab4-4717-9e0e-b7bf2b896287', 'math', 'Geometry (Area)', null, 'A regular hexagon is inscribed in a circle of radius 6. What is the area of the region inside the circle but outside the hexagon?', '["36π - 54√3","36π - 36√3","36π - 18√3","36π - 72√3"]'::jsonb, 0, 'The regular hexagon can be divided into 6 equilateral triangles, each with side length equal to the circle''s radius, 6. The area of one equilateral triangle is (√3/4) × 6^2 = 9√3, so the hexagon''s area is 6 × 9√3 = 54√3. The circle''s area is π × 6^2 = 36π. The area of the region inside the circle but outside the hexagon is 36π - 54√3.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '90a1322fbb001ef2b39b9987a536bdc11738e3cd17c935e08bb367f820c678f9') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-a0faf287-7bee-4722-9a31-df1c079b6fde', 'math', 'Geometry (Area)', null, 'A square is inscribed in a semicircle of radius 5 such that one side of the square lies on the diameter of the semicircle. What is the area of the square?', '["20","25","16","10"]'::jsonb, 0, 'Let the side length of the square be s. Place the semicircle''s center at the origin with the diameter along the x-axis. The square''s base lies on the diameter, so its top vertices are at (±s/2, s). These points lie on the semicircle, so (s/2)^2 + s^2 = 5^2. This gives s^2/4 + s^2 = 25, or (5/4)s^2 = 25, so s^2 = 20. The area of the square is s^2 = 20.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'ce344fa2021db2b6a7d19364a8ea9f173ffb18615cb1f30af76b4e52c9d9d130') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-acd6d576-73be-45e2-949f-9e4b60e7e69d', 'math', 'Geometry (Area)', null, 'In triangle ABC, points D and E lie on sides AB and AC respectively. AD:DB = 1:2 and AE:EC = 1:3. If the area of quadrilateral DBCE is 55, what is the area of triangle ADE?', '[]'::jsonb, 0, 'Let the area of triangle ADE be x. Then the area of triangle ABC is x + 55. Since AD/AB = 1/(1+2) = 1/3 and AE/AC = 1/(1+3) = 1/4, the ratio of the areas of triangle ADE to triangle ABC is (1/3)*(1/4) = 1/12. Set up the equation: x / (x + 55) = 1/12. Cross-multiply: 12x = x + 55. Solve: 11x = 55, so x = 5.', 'ai', true, 'hard', 'model', 'spr', '5', null, null, 'active', 'f6fac194635dabdeaa557b6b4e775392b6498813855a4bac8bbdfc0538d09106') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-8e8941c6-4a7f-406e-afa7-fb06ce228363', 'math', 'Geometry (Area)', null, 'A square with side length 12 has a circle inscribed in it. A second square is inscribed in the circle. A third square is inscribed in the circle that is inscribed in the second square. What is the area of the third square?', '[]'::jsonb, 0, 'Step 1: The first square has side 12, so its area is 144. The inscribed circle has diameter equal to the side of the square, so diameter = 12, radius = 6. Step 2: The second square is inscribed in this circle, so its diagonal equals the circle''s diameter, 12. The side of the second square is 12/√2 = 6√2, and its area is (6√2)^2 = 72. Step 3: The circle inscribed in the second square has diameter equal to the side of the second square, 6√2, so its radius is 3√2. Step 4: The third square is inscribed in this circle, so its diagonal equals the circle''s diameter, 6√2. Its side is (6√2)/√2 = 6, and its area is 6^2 = 36.', 'ai', true, 'hard', 'model', 'spr', '36', null, null, 'active', '5ccf915e4b58e8048d8330d31aff2e36a0c5a5a8bdda71e357d7f6be09dcdf6c') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-237bca0e-4054-4cbb-a3b0-8c175ef562ef', 'math', 'Geometry (Area)', null, 'In triangle ABC, points D, E, and F lie on sides BC, CA, and AB respectively. BD:DC = 1:2, CE:EA = 1:2, and AF:FB = 1:2. If the area of triangle ABC is 45, what is the area of triangle DEF?', '[]'::jsonb, 0, 'The area of triangle AFE is (AF/AB)*(AE/AC)*area(ABC) = (1/3)*(2/3)*45 = 10. Similarly, area of BDF = (1/3)*(2/3)*45 = 10, and area of CDE = (2/3)*(1/3)*45 = 10. The sum of the areas of these three corner triangles is 30. The area of triangle DEF is the area of ABC minus the sum of the corner triangles: 45 - 30 = 15.', 'ai', true, 'hard', 'model', 'spr', '15', null, null, 'active', 'b4f6e63508501a6c76f974ea583c2455bed31e61d106b6ffb1c2ffe26e94847e') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-6313396e-89cc-41b3-9a74-7cc7bdf28ca6', 'math', 'Geometry (Area)', null, 'A right triangle has legs of length 6 and 8. Squares are constructed outward on all three sides of the triangle. The outer vertices of these squares are connected in order to form a hexagon. What is the area of this hexagon?', '[]'::jsonb, 0, 'Place the right angle at (0,0) with legs along the positive x- and y-axes: vertices (0,0), (6,0), (0,8). The hypotenuse is 10. The squares on the legs have areas 36 and 64; the square on the hypotenuse has area 100. The hexagon can be decomposed into these three squares, the original triangle (area 24), and three additional triangles each congruent to the original. Alternatively, use coordinates: outer vertices are (0,-6), (6,-6), (14,6), (8,14), (-8,8), (-8,0). Shoelace formula gives area = 296. Summing areas: 36 + 64 + 100 + 4 × 24 = 296.', 'ai', true, 'hard', 'model', 'spr', '296', null, null, 'active', '54aaa613546eb60b591c6ce41354434158a3278e8754bcbf7aab0c00155542d2') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-19ab96b0-59b7-476b-a1a6-4130227fc2a8', 'math', 'Geometry (Triangles)', null, 'A right triangle has legs of length 3 and 4. What is the length of the hypotenuse?', '[]'::jsonb, 0, 'Use the Pythagorean theorem: a² + b² = c². Substitute the leg lengths: 3² + 4² = 9 + 16 = 25. The hypotenuse c = √25 = 5.', 'ai', true, 'easy', 'model', 'spr', '5', null, null, 'active', '42a73679b8daf218bec0836f0e65b6a8fb52de2f24b3308d950b08231ea61036') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-83b72c3d-2dd1-4b65-a3f1-8760ad82d9cc', 'math', 'Geometry (Triangles)', null, 'In a triangle, the measures of two angles are 50° and 60°. What is the measure, in degrees, of the third angle?', '[]'::jsonb, 0, 'The sum of the interior angles of a triangle is 180°. Subtract the given angles from 180°: 180 - 50 - 60 = 70.', 'ai', true, 'easy', 'model', 'spr', '70', null, null, 'active', '0b378a052b285d6d62796f8b19ae56214f2f0048850eccbc5f5e5b6b3aa95aef') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-ef398fe8-a704-455a-971e-7f675184f640', 'math', 'Geometry (Triangles)', null, 'In triangle ABC, angle A measures 50° and angle B measures 60°. What is the measure of angle C in degrees?', '[]'::jsonb, 0, 'The sum of the interior angles of a triangle is 180°. Subtract the given angles: 180 - 50 - 60 = 70. So angle C is 70°.', 'ai', true, 'easy', 'model', 'spr', '70', null, null, 'active', '23f52e2062455887099486b985d6937ce639273c50ad8cdee2b3e24bc404608e') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-966e7f10-6b82-4a75-9e01-671528640444', 'math', 'Geometry (Triangles)', null, 'A right triangle has legs of length 6 and 8. What is the length of the hypotenuse?', '[]'::jsonb, 0, 'Use the Pythagorean theorem: hypotenuse = √(6² + 8²) = √(36 + 64) = √100 = 10.', 'ai', true, 'easy', 'model', 'spr', '10', null, null, 'active', 'd9794f9a76e047770ef50c50566bd5a7a78c64b0dff03810c97ce9153a89d52a') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-e8b7415e-b2bc-4ac9-8ab8-d32fdb14bc11', 'math', 'Geometry (Triangles)', null, 'A right triangle has legs of length 6 and 8. What is the length of the hypotenuse?', '["10","14","48","100"]'::jsonb, 0, 'By the Pythagorean theorem, the hypotenuse is the square root of the sum of the squares of the legs: sqrt(6^2 + 8^2) = sqrt(36 + 64) = sqrt(100) = 10.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '5b6b9fd33490820c464b39eada12aeb645370cfc1a1b9f1a9beda3bf11842a24') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-919c11b9-cb51-4dc7-ac17-764e2e76c548', 'math', 'Geometry (Triangles)', null, 'In a triangle, two of the interior angles measure 50° and 60°. What is the measure of the third angle?', '["70°","80°","90°","110°"]'::jsonb, 0, 'The sum of the interior angles of any triangle is 180°. Subtract the given angles from 180°: 180 - 50 - 60 = 70°.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '85d492d2bba7f05db542b0d15f5b46effb335d79a3c48c85424019d1fa330480') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-a2028a8d-a56e-4c50-bc72-87c2144ee841', 'math', 'Geometry (Triangles)', null, 'A right triangle has legs of length 5 and 12. What is the length of the altitude drawn to the hypotenuse?', '["60/13","13","30/13","17"]'::jsonb, 0, 'The area of the triangle is (1/2)*5*12 = 30. The hypotenuse is sqrt(5^2 + 12^2) = 13. The altitude h to the hypotenuse satisfies (1/2)*13*h = 30, so h = 60/13.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '7c3b4f2605b5178cab54f76cec988b71e7071b4ba3f5b18bc8ed6e89d82aaa90') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-73191f69-8a20-417d-8f44-3f99c5ab233f', 'math', 'Geometry (Triangles)', null, 'In triangle ABC, the measure of angle A is 50° and the measure of angle B is 60°. What is the measure of the exterior angle at vertex C?', '["70°","110°","120°","130°"]'::jsonb, 1, 'The exterior angle at vertex C is equal to the sum of the two remote interior angles, A and B. 50° + 60° = 110°.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'f8cb0493bb7eeef5d7b7f4bd4420d21d3804873d9e82e2dadc48e23d251b76d4') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-115f9848-4d5d-4416-a78a-3c1024e65025', 'math', 'Geometry (Triangles)', null, 'In triangle ABC, the angle bisector of angle A meets side BC at point D. If AB = 8, AC = 12, and BD = 4, what is the length of DC?', '["6","2","8","3"]'::jsonb, 0, 'By the Angle Bisector Theorem, AB / AC = BD / DC. Substituting the given values: 8 / 12 = 4 / DC. Cross-multiplying gives 8 * DC = 48, so DC = 6.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'fcf22a0fed41e547a338e9d43596e6757905a5b3af86a889aee5f49dd708f890') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-939cb806-2976-40c9-bda1-30a93526686c', 'math', 'Geometry (Triangles)', null, 'A right triangle has legs of length 9 and 12. What is the area of the triangle?', '["54","108","15","21"]'::jsonb, 0, 'The area of a right triangle is (1/2) × leg1 × leg2. Substituting the given legs: (1/2) × 9 × 12 = 54.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '0d175968e0a12368824393998263d6f255b9c1df9165c1c868874a5aa0a18a6b') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-159d7c65-e513-45e6-98ec-67d656895607', 'math', 'Geometry (Triangles)', null, 'In isosceles triangle ABC, AB = AC. If angle B measures 70°, what is the measure of angle A?', '["40°","70°","55°","110°"]'::jsonb, 0, 'Since AB = AC, angles B and C are equal. Thus angle C = 70°. The sum of angles in a triangle is 180°, so angle A = 180° - 70° - 70° = 40°.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '039ae794826b4d34f1a300c2eec323ec588a9150454fa4239cd984ec7905658e') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-60bf6fe9-1e47-4074-99cd-4560c4521803', 'math', 'Geometry (Triangles)', null, 'A triangle has two sides of lengths 5 and 8. Which of the following could be the length of the third side?', '["2","3","12","14"]'::jsonb, 2, 'By the triangle inequality, the third side must be greater than the positive difference of the two given sides (8 - 5 = 3) and less than their sum (8 + 5 = 13). Only 12 satisfies 3 < x < 13.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '481a641894ad02603288847b80e4c623fb221ffd3892ff316ab144ebf766ca63') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-f01514ee-9a5d-4eac-a8b2-7af3ab97ca83', 'math', 'Geometry (Triangles)', null, 'In triangle ABC, points D and E lie on sides AB and AC, respectively, such that DE is parallel to BC. If AD = 3, DB = 2, and the area of trapezoid DBCE is 16, what is the area of triangle ADE?', '[]'::jsonb, 0, 'Since DE is parallel to BC, triangle ADE is similar to triangle ABC. The ratio of corresponding sides is AD/AB = 3/(3+2) = 3/5. The ratio of their areas is the square of the side ratio: (3/5)^2 = 9/25. Let x be the area of triangle ADE. Then area of triangle ABC = x + 16. Set up the proportion: x/(x+16) = 9/25. Cross-multiply: 25x = 9(x+16) => 25x = 9x + 144 => 16x = 144 => x = 9.', 'ai', true, 'hard', 'model', 'spr', '9', null, null, 'active', 'ec99d6ed59f4b9177559865d540024e93ed9e09b0d5d96ef26c52fe6aef142ef') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-7fd93769-64fa-468f-ac72-de0f1399d85c', 'math', 'Geometry (Triangles)', null, 'In right triangle ABC, angle B is a right angle, AB = 3, and BC = 4. Point D lies on hypotenuse AC such that BD is perpendicular to AC. What is the length of AD?', '[]'::jsonb, 0, 'First, find AC using the Pythagorean theorem: AC = sqrt(3^2 + 4^2) = 5. Triangles ABD and ABC are similar because they are both right triangles sharing angle A. Therefore, AD/AB = AB/AC. Substitute: AD/3 = 3/5. Solve: AD = 9/5.', 'ai', true, 'hard', 'model', 'spr', '9/5', null, null, 'active', 'ba091817abd0782f2736720c5b803c2bebfdb663b02c56e37ef239b358507cbd') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-dc0ec76a-b9ce-43e8-8d40-578e6b5f3952', 'math', 'Geometry (Triangles)', null, 'In triangle ABC, AB = 13, BC = 14, and CA = 15. Point P lies inside the triangle such that the areas of triangles PAB, PBC, and PCA are equal. What is the distance from P to side BC?', '["3","4","6","8"]'::jsonb, 1, 'Since the three triangles formed by P have equal area, P is the centroid of triangle ABC. The distance from the centroid to a side is one-third the altitude to that side. The area of triangle ABC is 84 (using Heron''s formula with semiperimeter s = 21: area = sqrt(21*8*7*6) = 84). The altitude from A to BC is 2*area/BC = 168/14 = 12. Therefore, the distance from P to BC is 12/3 = 4.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'bf856b02f3ba65585ee15f084b2d299b87355b6c6927393b3614dab32ec1e972') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-0c5e51ba-d014-4055-805c-330c3af59267', 'math', 'Geometry (Triangles)', null, 'In right triangle ABC, the right angle is at C. Altitude CD is drawn to hypotenuse AB. If CD = 6 and AC = 10, what is the length of BC?', '["7.5","8","9","12.5"]'::jsonb, 0, 'Let AD = x and DB = y. By the geometric mean relationships in a right triangle with altitude to the hypotenuse, CD^2 = AD * DB, so x*y = 36. Also, AC^2 = AD * AB, so x(x + y) = 100. Substituting xy = 36 gives x^2 + 36 = 100, so x^2 = 64 and x = 8. Then y = 36/8 = 4.5. The length of BC satisfies BC^2 = DB * AB = y(x + y) = 4.5 * 12.5 = 56.25, so BC = 7.5.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '0099a1753b0962d61e065e90fb43b3e0bc359e6e82de13bde2eeb6215f414d0e') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-55901712-9b41-4ac8-aace-da3f68abe317', 'math', 'Geometry (Triangles)', null, 'In triangle XYZ, XY = 5, YZ = 6, and ZX = 7. What is the cosine of angle Y?', '["1/3","1/4","1/5","1/6"]'::jsonb, 2, 'Using the Law of Cosines with angle Y opposite side XZ: (XZ)^2 = (XY)^2 + (YZ)^2 - 2*(XY)*(YZ)*cos(Y). Substitute: 7^2 = 5^2 + 6^2 - 2*5*6*cos(Y) => 49 = 25 + 36 - 60*cos(Y) => 49 = 61 - 60*cos(Y) => 60*cos(Y) = 12 => cos(Y) = 12/60 = 1/5.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'f5465110c4f862ccf8af217e51000d49cb7ba780d578cd7c7be3f7364b97e616') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-4e7f4879-692e-4865-9ae8-3efb3f3e9fa4', 'math', 'Geometry (Triangles)', null, 'In triangle ABC, AB = 13, BC = 14, and CA = 15. What is the length of the altitude from A to BC?', '["10","11","12","13"]'::jsonb, 2, 'First, find the area of triangle ABC using Heron''s formula. The semiperimeter s = (13+14+15)/2 = 21. Area = sqrt(21*(21-13)*(21-14)*(21-15)) = sqrt(21*8*7*6) = sqrt(7056) = 84. The altitude from A to BC uses BC as the base, so area = (1/2)*BC*h => 84 = (1/2)*14*h => h = 12.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '172f884439d1af8b4f752fd30b6bdf7a2bc123a25655ddce4c43099f4591b9e7') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-f8cb4945-5b60-48fa-b287-a588e6751628', 'math', 'Inequalities', null, 'Which of the following is the solution to the inequality 2x - 3 < 7?', '["x < 5","x > 5","x < 2","x > 2"]'::jsonb, 0, 'Add 3 to both sides to get 2x < 10, then divide by 2 to obtain x < 5.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'a01e6216357f75409d4e166542aaaf305fcac57bd0e688a0c11103bca909aea6') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-4cdf1d8c-5939-45a5-82c8-a473122aceae', 'math', 'Inequalities', null, 'A student must score at least 80 points on a test to earn a B. If s represents the score, which inequality models this condition?', '["s ≥ 80","s ≤ 80","s > 80","s < 80"]'::jsonb, 0, 'The phrase ''at least 80'' means 80 or higher, so the correct inequality is s ≥ 80.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'f11016e48517bdd9808b836dde5d2d79e7cc2d02f074ab13fcdb8c12f502a5ba') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-83cbf97c-7945-49a4-a8f8-94729c840cfa', 'math', 'Inequalities', null, 'Solve the inequality: 2x - 3 < 7', '["x < 5","x > 5","x < 2","x > 2"]'::jsonb, 0, 'Add 3 to both sides to get 2x < 10, then divide by 2 to obtain x < 5.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'a29fdf9456d9bda6e771ae7035474e3ef97f9695a88f9f0f325ff22af9e3cec0') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-a5b385eb-f4e0-472a-9bf0-60950e5a104e', 'math', 'Inequalities', null, 'A number n is at most 12. Which inequality represents this statement?', '["n ≤ 12","n ≥ 12","n < 12","n > 12"]'::jsonb, 0, 'The phrase ''at most'' means the number can be 12 or any value less than 12, which is represented by n ≤ 12.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', 'b2da26076a38e75a3581e6984cd44804fd931fc4f481e056e2c0fb90509deee0') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-c49c88fa-ea1d-4cd6-b9cf-780c1bad1af5', 'math', 'Inequalities', null, 'Which of the following values of x satisfies the inequality 2x - 3 > 1?', '["0","1","2","3"]'::jsonb, 3, 'Solve the inequality: 2x - 3 > 1 => 2x > 4 => x > 2. Among the choices, only 3 is greater than 2.', 'ai', true, 'easy', 'model', 'mcq', null, null, null, 'active', '6d379a549f773cadfc57e0dd4c719128b23f7afaf6a0dd9ee271c998a0ba51b7') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-060a53c1-cca8-44a1-a87a-b118677ff384', 'math', 'Inequalities', null, 'If 4x + 1 < 13, what is the greatest integer value of x?', '[]'::jsonb, 0, 'Subtract 1 from both sides: 4x < 12. Divide both sides by 4: x < 3. The greatest integer less than 3 is 2.', 'ai', true, 'easy', 'model', 'spr', '2', null, null, 'active', '3aeb3418846c0a749bcae0cbaa19536a7d7146d5bcec5b570dd99a1e7d4f979d') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-959a3426-54e2-4d68-b8f9-a32a6acf9b56', 'math', 'Inequalities', null, 'What is the solution set for the inequality |2x - 1| ≤ 5?', '["-2 ≤ x ≤ 3","x ≤ 3","x ≥ -2","-3 ≤ x ≤ 2"]'::jsonb, 0, 'Rewrite the absolute value inequality as a compound inequality: -5 ≤ 2x - 1 ≤ 5. Add 1 to all parts: -4 ≤ 2x ≤ 6. Divide by 2: -2 ≤ x ≤ 3.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '9320c35f3f58acc3ef27bbdea238a8ce4fecccf5adf0a53a80d21dc4b6f6702b') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-c5b9d239-7472-4cea-8d94-6cf6e69a1f56', 'math', 'Inequalities', null, 'Which of the following is equivalent to the inequality -5 ≤ 3 - 2x < 7?', '["-2 < x ≤ 4","-2 ≤ x < 4","-2 < x < 4","-2 ≤ x ≤ 4"]'::jsonb, 0, 'Subtract 3 from all parts: -8 ≤ -2x < 4. Divide by -2, reversing the inequality signs: 4 ≥ x > -2, which is equivalent to -2 < x ≤ 4.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'ebc0fa20bb2f674dfe3e58bf59b6633567c063b277c064a66f13c493cf47d9b2') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-32cd1972-bae6-4c2f-90a5-c8d37f067183', 'math', 'Inequalities', null, 'If 4x - 9 > 2x + 3, what is the least possible integer value of x?', '["5","6","7","8"]'::jsonb, 2, 'Subtract 2x from both sides: 2x - 9 > 3. Add 9: 2x > 12. Divide by 2: x > 6. The smallest integer greater than 6 is 7.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '59d89e66372f5a660830f3507b9b83529c15350cd05d7435f760de4497e2089f') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-ad9e501f-00d6-41cb-b34d-722f52042613', 'math', 'Inequalities', null, 'Solve the inequality: -2x + 5 > 9.', '["x < -2","x > -2","x < 2","x > 2"]'::jsonb, 0, 'Subtract 5 from both sides to get -2x > 4. Divide by -2, remembering to reverse the inequality sign, yielding x < -2. The correct choice is x < -2.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'c599208731eb30fbae0fb5dcbfef4319cc9c70faf5e4fd386b0e086436296618') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-e3ebcfa9-9cc4-4342-912a-04a08dbe18d5', 'math', 'Inequalities', null, 'If 3 ≤ 2x - 1 < 7, what is the solution set for x?', '["2 ≤ x < 4","2 < x ≤ 4","1 ≤ x < 3","1 < x ≤ 3"]'::jsonb, 0, 'Add 1 to all three parts of the inequality: 4 ≤ 2x < 8. Then divide all parts by 2: 2 ≤ x < 4. The correct solution set is 2 ≤ x < 4.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', '544da2025de11198cd14a1f918ad505606cec052c7ac98bdbf7c203cb03d5aa7') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-7921b86b-ccd9-4f08-9638-83cc6e13b9d5', 'math', 'Inequalities', null, 'Which of the following is the solution to the inequality -2x + 5 > 11?', '["x > -3","x < -3","x > 3","x < 3"]'::jsonb, 1, 'Subtract 5 from both sides to get -2x > 6. Divide by -2 and reverse the inequality sign, yielding x < -3. The correct choice is x < -3.', 'ai', true, 'medium', 'model', 'mcq', null, null, null, 'active', 'bad6962038c0c5c9be7a6ed35f20d7dc20746e2d405438e2962102f55ecf8b71') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-50aad7ef-754a-48a7-ba6d-e3f02b566091', 'math', 'Inequalities', null, 'Solve the inequality \(\frac{x+1}{x-2} \leq 0\).', '["-1 ≤ x < 2","x ≤ -1 or x > 2","-1 < x ≤ 2","x < -1 or x ≥ 2"]'::jsonb, 0, 'The expression is zero when the numerator is zero (x = -1) and undefined when the denominator is zero (x = 2). Test intervals: for x < -1, both numerator and denominator are negative, so the fraction is positive. For -1 < x < 2, numerator positive, denominator negative, so the fraction is negative. For x > 2, both positive, fraction positive. Including the zero at x = -1 and excluding the undefined point at x = 2 gives the solution -1 ≤ x < 2.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'f71c0ed63f78923bea16c9cca5490e93bd27a2e8aa78fd736075b45618062d7e') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-9baf41df-6574-41a1-afbb-96d0c9c0e1e7', 'math', 'Inequalities', null, 'A factory produces two types of products, A and B. Each unit of product A requires 2 hours of assembly and 1 hour of testing. Each unit of product B requires 1 hour of assembly and 3 hours of testing. The factory has at most 100 hours available for assembly and at most 90 hours available for testing. If x represents the number of units of product A and y represents the number of units of product B, which system of inequalities represents the constraints?', '["2x + y ≤ 100, x + 3y ≤ 90, x ≥ 0, y ≥ 0","2x + y ≥ 100, x + 3y ≥ 90, x ≥ 0, y ≥ 0","x + 2y ≤ 100, 3x + y ≤ 90, x ≥ 0, y ≥ 0","2x + 3y ≤ 100, x + y ≤ 90, x ≥ 0, y ≥ 0"]'::jsonb, 0, 'Assembly time: 2 hours per A and 1 hour per B, total at most 100 hours, so 2x + y ≤ 100. Testing time: 1 hour per A and 3 hours per B, total at most 90 hours, so x + 3y ≤ 90. Non-negativity constraints: x ≥ 0, y ≥ 0. The correct choice matches these inequalities.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '7f38b47ded1876e301d6430028b2450ab5ec68d5d25975d543559e9d9773036f') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-61cc9867-889b-498f-85d1-3e3152997633', 'math', 'Inequalities', null, 'Find the sum of all integer values of x that satisfy the inequality (x^2 - 5x + 6)/(x^2 - 1) <= 0.', '[]'::jsonb, 0, 'Factor the numerator and denominator: (x-2)(x-3)/((x-1)(x+1)) <= 0. The critical points are x = -1, 1, 2, 3. Create a sign chart: for x < -1, all factors are negative, so the expression is positive. For -1 < x < 1, (x-1) negative, others negative/positive? Actually (x-2) and (x-3) negative, (x-1) negative, (x+1) positive => negative/positive = negative, so <=0 true. For 1 < x < 2, (x-1) positive, (x-2) negative, (x-3) negative, (x+1) positive => positive/positive = positive. For 2 <= x <= 3, (x-2) nonnegative, (x-3) nonpositive, (x-1) positive, (x+1) positive => nonpositive/positive <=0 true. For x > 3, all positive => positive. Include zeros at x=2 and x=3, exclude undefined at x=±1. Solution set: -1 < x < 1 or 2 <= x <= 3. Integer solutions: 0, 2, 3. Sum = 0+2+3 = 5.', 'ai', true, 'hard', 'model', 'spr', '5', null, null, 'active', 'a65939fa93642e696027f4f52095c7a9ad3caf695ffc07e0a24680aca137f3da') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-77d484b5-c51b-4b6c-a8e7-4b285ec37b6b', 'math', 'Inequalities', null, 'How many ordered pairs of integers (x, y) satisfy the inequality |x - 2| + |y + 1| <= 3?', '[]'::jsonb, 0, 'The inequality describes a diamond-shaped region in the coordinate plane centered at (2, -1) with a ''radius'' of 3. For each integer x from -1 to 5, the allowed integer y values satisfy |y + 1| <= 3 - |x - 2|. Counting the integer points: when x = 2, |x-2|=0, so |y+1| <= 3 gives y = -4,-3,-2,-1,0,1,2 (7 points). For x = 1 and 3, |x-2|=1, so |y+1| <= 2 gives 5 points each. For x = 0 and 4, |x-2|=2, so |y+1| <= 1 gives 3 points each. For x = -1 and 5, |x-2|=3, so |y+1| <= 0 gives 1 point each. Total = 7 + 2*5 + 2*3 + 2*1 = 7 + 10 + 6 + 2 = 25.', 'ai', true, 'hard', 'model', 'spr', '25', null, null, 'active', 'f5250113767092525e02bf3c3ba07011336a622ca19569299b1d2a562c2d6585') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-e180dc8e-8640-4b09-875a-13c700e52534', 'math', 'Inequalities', null, 'Which of the following represents all real numbers x that satisfy the inequality (x^2 - 4)/(x - 1) ≤ 0?', '["x ≤ -2 or 1 < x ≤ 2","x ≤ -2 or 1 ≤ x ≤ 2","x < -2 or 1 < x < 2","x ≤ -2 or 1 < x < 2"]'::jsonb, 0, 'Factor the numerator as (x-2)(x+2). The inequality becomes ((x-2)(x+2))/(x-1) ≤ 0. Critical points are x = -2, 1, 2. Test intervals: for x < -2, the expression is negative or zero; for -2 < x < 1, it is positive; for 1 < x < 2, it is negative; for x > 2, it is positive. The expression equals zero at x = -2 and x = 2, and is undefined at x = 1. Therefore, the solution set is x ≤ -2 or 1 < x ≤ 2. The correct choice is ''x ≤ -2 or 1 < x ≤ 2''.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', 'e5d0fbbb29b433ee5882e1897142917b3818f8003ee0b4aba8f500be048d27f2') on conflict (id) do nothing;
insert into sat.questions (id, section, skill, passage, prompt, choices, answer_index, explanation, source, enabled, difficulty, difficulty_source, response_format, correct_answer, answer_tolerance, figure, review_status, dedup_hash) values ('ai-b46c01e7-8a51-482a-96b3-5294a90c4809', 'math', 'Inequalities', null, 'What is the solution set of the inequality |x^2 - 5x| < 6?', '["-1 < x < 2 or 3 < x < 6","-1 < x < 6","x < -1 or 2 < x < 3 or x > 6","-1 < x < 2 and 3 < x < 6"]'::jsonb, 0, 'Rewrite the absolute value inequality as -6 < x^2 - 5x < 6. This yields two quadratic inequalities: x^2 - 5x + 6 > 0 and x^2 - 5x - 6 < 0. Factor to get (x-2)(x-3) > 0 and (x-6)(x+1) < 0. The first gives x < 2 or x > 3; the second gives -1 < x < 6. The intersection of these solution sets is -1 < x < 2 or 3 < x < 6. The correct choice is ''-1 < x < 2 or 3 < x < 6''.', 'ai', true, 'hard', 'model', 'mcq', null, null, null, 'active', '086f71d49d2d069b78f001d6da804daf2d35f8d81019681007aa61e75f89e127') on conflict (id) do nothing;
